CARDIO.register({"item":"203","meta":{"num":203,"short":"Dyspnée","title":"Dyspnée aiguë et chronique","section":"IV","chapter":17,"pages":"441-454","sdd":[{"num":18,"label":"Découverte d'anomalies à l'auscultation cardiaque"},{"num":20,"label":"Découverte d'anomalies à l'auscultation pulmonaire"},{"num":145,"label":"Douleur pharyngée"},{"num":149,"label":"Ingestion ou inhalation d'un corps étranger"},{"num":160,"label":"Détresse respiratoire aiguë"},{"num":162,"label":"Dyspnée"},{"num":163,"label":"Expectoration"},{"num":167,"label":"Toux"},{"num":223,"label":"Interprétation de l'hémogramme"},{"num":283,"label":"Consultation de suivi et éducation thérapeutique d'un patient asthmatique"},{"num":285,"label":"Consultation de suivi et éducation thérapeutique d'un patient avec un antécédent cardiovasculaire"},{"num":286,"label":"Consultation de suivi et éducation thérapeutique d'un patient BPCO"},{"num":287,"label":"Consultation de suivi et éducation thérapeutique d'un patient insuffisant cardiaque"}]},"objectives":[{"id":"203-obj-01","rank":"A","rubric":"Définition","title":"Définition de la dyspnée et de ses formes inspiratoire et expiratoire","desc":""},{"id":"203-obj-02","rank":"A","rubric":"Diagnostic positif","title":"Connaître l'examen clinique d'un patient dyspnéique","desc":""},{"id":"203-obj-03","rank":"A","rubric":"Étiologies","title":"Connaître les principales étiologies d'une dyspnée aiguë et leurs signes cliniques","desc":"OAP, embolie pulmonaire, crise d'asthme, exacerbation de BPCO, pneumopathie, pneumothorax, SDRA, inhalation de corps étranger, œdème de Quincke, anémie aiguë"},{"id":"203-obj-04","rank":"A","rubric":"Diagnostic positif","title":"Connaître les signes de gravité devant une dyspnée aiguë","desc":""},{"id":"203-obj-05","rank":"A","rubric":"Diagnostic positif","title":"Connaître les éléments d'orientation diagnostique devant une dyspnée chronique","desc":""},{"id":"203-obj-06","rank":"A","rubric":"Étiologies","title":"Connaître les signes d'orientation étiologique","desc":""},{"id":"203-obj-07","rank":"A","rubric":"Examens complémentaires","title":"Connaître les examens complémentaires de 1re intention selon le caractère aigu ou chronique","desc":""},{"id":"203-obj-08","rank":"A","rubric":"Examens complémentaires","title":"Connaître les examens complémentaires de 2e intention selon le caractère aigu ou chronique","desc":""},{"id":"203-obj-09","rank":"B","rubric":"Étiologies","title":"Connaître les étiologies plus rares d'une dyspnée aiguë","desc":"Pseudo-asthme cardiaque, tamponnade, états de choc, acidose métabolique, hyperthermie, sténoses trachéales, intoxication au CO, pneumocystose"},{"id":"203-obj-10","rank":"A","rubric":"Étiologies","title":"Connaître les principales étiologies cardiaques et pulmonaires d'une dyspnée chronique","desc":""},{"id":"203-obj-11","rank":"A","rubric":"Suivi et/ou pronostic","title":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","desc":""},{"id":"203-obj-12","rank":"B","rubric":"Prise en charge","title":"Connaître les indications des examens radiologiques devant une dyspnée aiguë et chronique","desc":""},{"id":"203-obj-13","rank":"A","rubric":"Définition","title":"Définir la dyspnée et la distinguer de la détresse et de l'insuffisance respiratoires","desc":""},{"id":"203-obj-14","rank":"A","rubric":"Diagnostic positif","title":"Connaître les éléments d'orientation étiologique devant une dyspnée aiguë","desc":""},{"id":"203-obj-15","rank":"A","rubric":"Identifier une urgence","title":"Connaître les signes de gravité accompagnant une dyspnée aiguë","desc":""},{"id":"203-obj-16","rank":"A","rubric":"Examens complémentaires","title":"Connaître la stratégie d'exploration en imagerie devant une dyspnée aiguë de l'enfant","desc":""},{"id":"203-obj-17","rank":"A","rubric":"Examens complémentaires","title":"Connaître les signes radiographiques indirects d'un corps étranger bronchique","desc":""},{"id":"203-obj-18","rank":"A","rubric":"Contenu multimédia","title":"Reconnaître une radiographie de thorax de face évocatrice d'un corps étranger","desc":""}],"course":{"sections":[{"id":"203-sec-01","title":"Définition et sémiologie générale de la dyspnée","rank":"A","objectives":["203-obj-01","203-obj-02","203-obj-13"],"content":"**Dyspnée** : sensation subjective et désagréable de gêne respiratoire, ressentie pour un niveau d'activité habituellement bien toléré. C'est un symptôme très fréquent, aux causes multiples : ORL, pneumologiques, cardiologiques, neurologiques.\n\n> Dyspnée et **insuffisance respiratoire (IR)** ne sont pas synonymes :\n> - une dyspnée peut exister **sans IR** (ex. anémie aiguë) ;\n> - une IR peut survenir **sans dyspnée** (ex. coma).\n\nOn distingue deux cadres temporels :\n- **dyspnée aiguë** : apparue en quelques heures à quelques jours ;\n- **dyspnée chronique** : apparue en quelques semaines à quelques mois.\n\n**Interrogatoire** — il évalue d'abord le terrain (antécédents, comorbidités, traitements en cours), puis caractérise la dyspnée :\n- rapidité d'installation (aiguë/chronique) ;\n- circonstances de survenue : repos ou effort ; **orthopnée** (dyspnée de décubitus) ou **platypnée** (dyspnée d'orthostatisme) ; facteur déclenchant saisonnier, climatique, environnemental ou toxique ; horaire ;\n- signes fonctionnels associés : généraux, respiratoires, cardiologiques, ORL, neurologiques.\n\n[A] Chez l'enfant comme chez l'adulte, il faut bien séparer trois notions proches mais distinctes : la dyspnée (sensation subjective), la détresse respiratoire (tableau clinique d'épuisement) et l'insuffisance respiratoire (défaillance des échanges gazeux).","keyPoints":["La dyspnée est une sensation subjective, non synonyme d'insuffisance respiratoire.","Dyspnée aiguë : heures à jours ; dyspnée chronique : semaines à mois.","Orthopnée = dyspnée de décubitus ; platypnée = dyspnée d'orthostatisme.","L'interrogatoire précise le terrain, le mode d'installation, les circonstances et les signes associés.","Bien distinguer dyspnée, détresse respiratoire et insuffisance respiratoire, en particulier chez l'enfant."],"pitfalls":["Croire qu'une dyspnée implique forcément une insuffisance respiratoire, ou l'inverse."],"src":"p. 442-443"},{"id":"203-sec-02","title":"Évaluation de l'intensité : NYHA, MRC, EVA, Borg","rank":"A","objectives":["203-obj-02"],"content":"L'intensité de la dyspnée **chronique** se mesure surtout par la classification de la **New York Heart Association (NYHA)**, la plus utilisée en cardiologie :\n\n| Stade NYHA | Définition |\n|---|---|\n| I | Aucune gêne dans la vie courante pour les efforts habituels |\n| II | Dyspnée pour des efforts importants (marche rapide, côte, montée de plus de 2 étages) |\n| III | Dyspnée pour des efforts peu intenses (marche en terrain plat, moins de 2 étages) |\n| IV | Dyspnée permanente, de repos ou pour des efforts minimes (toilette, habillage) |\n\nL'échelle **MRC (Medical Research Council)**, utilisée en pneumologie, s'en rapproche :\n\n| Stade MRC | Définition |\n|---|---|\n| 0 | Dyspnée uniquement pour un exercice intense |\n| 1 | Marche rapide en terrain plat ou montée d'une pente légère |\n| 2 | Marche à plat plus lente que les sujets du même âge, ou arrêts imposés au rythme propre |\n| 3 | Arrêt nécessaire après environ 100 m ou après quelques minutes de marche |\n| 4 | Empêche de sortir du domicile, ou survient à l'habillage |\n\nPour la dyspnée **aiguë**, l'intensité peut être évaluée par :\n- une **échelle visuelle analogique (EVA)** de 10 cm (0 = absence de dyspnée, 10 = maximale) ;\n- l'**échelle de Borg** de 0 à 10 (utilisable aussi après un exercice déterminé) ;\n- le **nombre d'oreillers** utilisés la nuit en cas d'orthopnée.","keyPoints":["La NYHA (I à IV) est la classification de référence de la dyspnée chronique.","Stade III NYHA = dyspnée pour la marche à plat ou moins de 2 étages ; stade IV = dyspnée permanente.","L'échelle MRC (0 à 4) est l'équivalent utilisé en pneumologie.","EVA et échelle de Borg (0-10) graduent l'intensité d'une dyspnée aiguë.","Le nombre d'oreillers utilisés la nuit reflète l'orthopnée."],"pitfalls":["Confondre les seuils NYHA (>2 étages en stade II, <2 étages en stade III) avec ceux de la MRC."],"src":"p. 443"},{"id":"203-sec-03","title":"Examen clinique et signes de gravité de la dyspnée aiguë","rank":"A","objectives":["203-obj-02","203-obj-04","203-obj-11","203-obj-15"],"content":"**Caractériser la dyspnée** à l'examen consiste à préciser :\n- la phase du cycle concernée : dyspnée **inspiratoire**, **expiratoire** ou aux deux temps ;\n- la **fréquence respiratoire** : tachypnée/polypnée si > 20 cycles/min, bradypnée si < 10 cycles/min ;\n- le **rythme** : régulier ou irrégulier, avec deux formes particulières — dyspnée de **Kussmaul** (inspiration, pause, expiration, pause), typique de l'acidose métabolique, et dyspnée de **Cheyne-Stokes** (polypnée croissante puis décroissante entrecoupée d'apnées), observée dans l'insuffisance cardiaque grave (origine centrale, bas débit cérébral) ;\n- l'**intensité** : hyperpnée (volume courant augmenté) ou hypopnée/oligopnée (volume courant diminué).\n\n**Orientation étiologique** : rechercher des signes généraux (fièvre, frissons, amaigrissement), des symptômes associés (douleur thoracique, toux, expectoration, wheezing, cornage), des anomalies auscultatoires (crépitants, sibilants, râles bronchiques, abolition du murmure vésiculaire) et une anomalie de percussion (matité, tympanisme), puis compléter par un examen cardiovasculaire (signes d'IC, thrombose veineuse), ORL, thyroïdien et neuromusculaire.\n\n**Signes de gravité** de la dyspnée aiguë :\n- mise en jeu des muscles respiratoires accessoires : tirage sus-sternal/sus-claviculaire, creusement intercostal, battement des ailes du nez, balancement thoraco-abdominal ;\n- cyanose, sueurs, **tachycardie > 120/min**, signes de choc (marbrures), angoisse, **SpO2 < 90 %** ;\n- retentissement neurologique : astérixis, agitation, somnolence, coma.\n\n> Ces signes imposent des décisions thérapeutiques immédiates, quel que soit l'âge du patient.","keyPoints":["Distinguer dyspnée inspiratoire, expiratoire et aux deux temps oriente déjà l'étiologie.","Tachypnée > 20/min, bradypnée < 10/min.","Dyspnée de Kussmaul = acidose métabolique ; Cheyne-Stokes = insuffisance cardiaque grave (origine centrale).","Les signes de lutte, la cyanose/tachycardie > 120/choc/SpO2 < 90 % et les signes neurologiques définissent la gravité.","Tout signe de gravité impose une décision thérapeutique immédiate."],"pitfalls":["Négliger les signes neurologiques (agitation, somnolence) qui sont des marqueurs de gravité au même titre que les signes respiratoires.","Oublier l'examen cardiovasculaire, ORL, thyroïdien et neuromusculaire lors de la recherche étiologique."],"src":"p. 444"},{"id":"203-sec-04","title":"Examens complémentaires devant une dyspnée","rank":"A","objectives":["203-obj-07","203-obj-08","203-obj-12","203-obj-16"],"content":"**Devant une dyspnée aiguë, en 1re intention :**\n- **gazométrie artérielle** : apprécie la gravité (hypoxémie, hypercapnie) et oriente parfois l'étiologie ; une SpO2 < 90 % traduit une hypoxémie et impose l'oxygénothérapie ;\n- **ECG** : recherche embolie pulmonaire, coronaropathie, trouble du rythme ;\n- **radiographie de thorax** : anomalie pariétale, pleurale, parenchymateuse, médiastinale, cardiomégalie ;\n- **biologie** : NFP, ionogramme, glycémie, BNP/NT-proBNP, D-dimères si suspicion d'embolie pulmonaire.\n\n> Devant une dyspnée aiguë, un **BNP < 100 pg/mL** (ou **NT-proBNP < 300 pg/mL**) rend le diagnostic d'insuffisance cardiaque peu probable ; à l'inverse, des valeurs supérieures sont en faveur d'une IC.\n> [B] Les seuils varient en réalité avec l'âge : les recommandations ESC 2021 retiennent, pour le NT-proBNP, > 450 pg/mL avant 55 ans, > 900 pg/mL entre 55 et 75 ans, > 1 800 pg/mL après 75 ans.\n> Un taux de D-dimères < 500 pg/mL permet d'exclure une embolie pulmonaire si la probabilité clinique est faible ou intermédiaire.\n\n**En 2e intention**, selon l'orientation initiale : écho-doppler veineux des membres inférieurs et/ou angioscanner pulmonaire et/ou scintigraphie pulmonaire de ventilation/perfusion (suspicion d'embolie pulmonaire) ; échocardiographie doppler ; épreuves fonctionnelles respiratoires ; cathétérisme cardiaque ; épreuve d'effort métabolique.\n\n**Devant une dyspnée chronique**, le bilan n'est pas urgent : NFP (éliminer une anémie), EFR avec gazométrie, ECG, échocardiographie doppler, radiographie de thorax, épreuve d'effort avec mesure des gaz respiratoires (oriente vers une cause cardiaque ou pulmonaire), scanner thoracique, cathétérisme cardiaque.\n\n[A] Chez l'enfant, une stratégie d'imagerie ciblée est nécessaire devant une dyspnée aiguë, en particulier pour rechercher les signes radiographiques indirects d'un corps étranger bronchique inhalé.","keyPoints":["1re intention (dyspnée aiguë) : gazométrie, ECG, radiographie de thorax, bilan biologique avec BNP/NT-proBNP et D-dimères.","BNP < 100 ou NT-proBNP < 300 pg/mL : IC peu probable devant une dyspnée aiguë.","[B] Seuils de NT-proBNP ESC 2021 croissants avec l'âge : 450 / 900 / 1 800 pg/mL.","D-dimères bas excluent l'EP si probabilité clinique faible ou intermédiaire.","Dyspnée chronique : toujours éliminer une anémie avant un bilan approfondi.","L'épreuve d'effort avec mesure des gaz objective la gêne et oriente cardiaque vs pulmonaire."],"pitfalls":["Oublier d'ajuster l'interprétation du NT-proBNP à l'âge du patient.","Méconnaître qu'une SpO2 < 90 % impose l'oxygénothérapie sans attendre la gazométrie."],"src":"p. 444-445"},{"id":"203-sec-05","title":"Étiologies cardiaques de la dyspnée aiguë","rank":"A","objectives":["203-obj-03","203-obj-09"],"content":"L'origine cardiaque est la **cause la plus fréquente** de dyspnée aiguë.\n\n**Œdème aigu du poumon (OAP)** : orthopnée, wheezing, crépitants bilatéraux, expectoration rose saumonée ; terrain de cardiopathie connue ou antécédent d'infarctus, facteur déclenchant (ex. passage en FA) ; radiographie : œdème alvéolaire, cardiomégalie ; ECG : séquelle de nécrose, FA rapide ; BNP/NT-proBNP augmentés. La réponse favorable au traitement (diurétique, trinitrine IV) conforte le diagnostic.\n\n**Troubles du rythme cardiaque mal tolérés** : tachycardies supraventriculaires et tachycardie ventriculaire peuvent s'accompagner d'une dyspnée aiguë.\n\n[B] **Pseudo-asthme cardiaque** : équivalent d'OAP à forme bronchospastique ; orthopnée, sibilants ± crépitants à l'auscultation — piège fréquent avec l'asthme vrai.\n\n[B] **Tamponnade** : complication d'une péricardite avec épanchement ; orthopnée, tachycardie, assourdissement des bruits du cœur, auscultation pulmonaire normale, turgescence jugulaire, pouls paradoxal (diminuant à l'inspiration profonde) ; tableau évocateur d'un collapsus avec signes d'insuffisance ventriculaire droite.\n\n[B] **Choc cardiogénique** : la dyspnée n'est pas au premier plan, le tableau est dominé par le collapsus et les signes d'hypoperfusion périphérique.","keyPoints":["L'OAP est la cause cardiaque la plus fréquente de dyspnée aiguë.","OAP : orthopnée, crépitants bilatéraux, expectoration rose saumonée, BNP élevé.","Pseudo-asthme cardiaque : sibilants trompeurs, équivalent d'OAP.","Tamponnade : orthopnée + auscultation pulmonaire normale + pouls paradoxal + turgescence jugulaire.","Dans le choc cardiogénique, la dyspnée passe au second plan derrière le collapsus."],"pitfalls":["Étiqueter un pseudo-asthme cardiaque comme crise d'asthme devant des sibilants isolés.","Oublier la tamponnade devant une dyspnée avec auscultation pulmonaire normale."],"src":"p. 446-447"},{"id":"203-sec-06","title":"Embolie pulmonaire aiguë","rank":"A","objectives":["203-obj-03"],"content":"[A] L'embolie pulmonaire est une cause **très fréquente** de dyspnée aiguë, dont le diagnostic reste souvent difficile.\n\n**Éléments d'orientation :**\n- recherche systématique d'un **contexte favorisant** : alitement, voyage de longue durée, immobilisation plâtrée, période postopératoire, etc. ;\n- installation en règle **brutale**, mais dyspnée d'intensité variable, souvent associée à une **douleur thoracique** ;\n- auscultation cardiaque et pulmonaire **souvent normale**, sauf tachycardie ;\n- gazométrie artérielle : **effet shunt** (hypoxie associée à une hypocapnie).\n\n> Une dyspnée aiguë isolée, sans autre signe d'orientation, doit systématiquement faire évoquer une embolie pulmonaire — la douleur thoracique n'est pas constante.\n\nSur le plan biologique, un taux de **D-dimères** bas contribue à exclure le diagnostic lorsque la probabilité clinique est faible ou intermédiaire ; à l'inverse, l'absence d'orientation franche vers une autre cause (pas de crépitants, pas de syndrome pleural, auscultation normale) renforce la suspicion d'embolie pulmonaire dans la démarche diagnostique globale devant une dyspnée aiguë.","keyPoints":["L'embolie pulmonaire est fréquente et son diagnostic est souvent difficile.","Toujours rechercher un contexte favorisant (alitement, voyage, chirurgie, plâtre).","Début brutal, dyspnée variable, souvent associée à une douleur thoracique.","Auscultation le plus souvent normale ; gazométrie en effet shunt (hypoxie-hypocapnie).","Une dyspnée aiguë isolée doit faire évoquer une EP même sans douleur.","Des D-dimères bas contribuent à l'exclure si la probabilité clinique n'est pas forte."],"pitfalls":["Écarter le diagnostic d'EP devant une auscultation normale, alors que c'est habituel."],"src":"p. 447"},{"id":"203-sec-07","title":"Étiologies pulmonaires et pleurales de la dyspnée aiguë","rank":"A","objectives":["203-obj-03"],"content":"**Crise d'asthme** : dyspnée expiratoire avec sibilants. À distinguer de l'**asthme aigu grave** (urgence vitale) : thorax bloqué en inflation, disparition des sibilants et du murmure vésiculaire, pouls paradoxal possible, élocution impossible.\n\n**Exacerbation de BPCO** : survient souvent lors d'une surinfection bronchique ; on parle d'exacerbation devant une majoration de la dyspnée, de la toux, du volume ou de la purulence des expectorations, chez un patient tabagique ou BPCO/emphysémateux connu ; dyspnée expiratoire avec sibilants, toux, expectoration, parfois hippocratisme digital. Rechercher des signes de gravité : dyspnée de repos, cyanose, désaturation, **polypnée > 25/min**, défaillance hémodynamique, signes neurologiques, hypercapnie.\n\n**Pneumopathie infectieuse** : syndrome infectieux (fièvre, toux, expectoration purulente, parfois douleur thoracique) ; foyer de crépitants ± syndrome de condensation ; radiographie avec opacité parenchymateuse systématisée.\n\n**SDRA** : forme sévère de défaillance pulmonaire aiguë, avec augmentation de la perméabilité alvéolocapillaire, mortalité élevée, œdème pulmonaire lésionnel (à distinguer de l'œdème hémodynamique) ; causes multiples (pneumopathie, sepsis, inhalation, embolie pulmonaire, traumatisme, choc, toxique) ; traitement en réanimation.\n\n**Atélectasies** pulmonaires bénignes ou malignes : diagnostic radiologique.\n\n**Étiologies pleurales** : **pneumothorax** (sujet longiligne, tabac, emphysème, début brutal parfois à l'effort, douleur latérothoracique, abolition des vibrations vocales et du murmure vésiculaire, tympanisme, hyperclarté radiographique) ou **épanchement pleural**.\n\n[A] **Traumatismes du thorax** : hémopéricarde, contusion pulmonaire, pneumothorax, pneumomédiastin, hémothorax, volet thoracique.","keyPoints":["Asthme aigu grave : silence auscultatoire, thorax bloqué, élocution impossible = urgence vitale.","Exacerbation de BPCO définie par majoration dyspnée/toux/expectoration ; gravité si polypnée > 25/min.","Pneumopathie : fièvre + foyer de crépitants + opacité systématisée.","Le SDRA est un œdème lésionnel grave, à distinguer de l'œdème hémodynamique, traité en réanimation.","Pneumothorax : abolition MV et vibrations vocales, tympanisme, hyperclarté.","Les traumatismes thoraciques exposent à hémopéricarde, pneumo/hémothorax, volet costal."],"pitfalls":["Confondre œdème lésionnel du SDRA et OAP hémodynamique.","Méconnaître l'asthme aigu grave car les sibilants ont disparu (silence auscultatoire trompeur)."],"src":"p. 447-449"},{"id":"203-sec-08","title":"Étiologies laryngotrachéales et autres causes de dyspnée aiguë","rank":"A","objectives":["203-obj-03","203-obj-09","203-obj-16","203-obj-17","203-obj-18"],"content":"[A] Les causes **laryngotrachéales** se traduisent typiquement par une **dyspnée inspiratoire**, avec bradypnée inspiratoire, cornage, tirage ; une dysphonie associée oriente vers une origine laryngée. Elles comprennent :\n- l'**œdème de Quincke**, avec œdème de la glotte, souvent dans un contexte de choc anaphylactique ;\n- l'**inhalation de corps étranger**, surtout chez l'enfant ;\n- des causes infectieuses de l'enfant : épiglottite, laryngite ;\n- des causes trachéales : sténose tumorale endoluminale ou extraluminale, corps étranger, granulome post-intubation.\n\n[A] Chez l'enfant, une stratégie d'imagerie adaptée doit être connue devant une dyspnée aiguë, avec identification des **signes radiographiques indirects** évocateurs d'un corps étranger bronchique inhalé, et reconnaissance d'une radiographie de thorax de face typique dans ce contexte.\n\n**Autres étiologies** de dyspnée aiguë :\n- [B] les **états de choc** ;\n- l'**acidose métabolique** ;\n- [A] les **causes neurologiques** : atteintes bulbaires, polyradiculonévrite, myasthénie ;\n- l'**intoxication au monoxyde de carbone** ;\n- l'**anémie aiguë** ;\n- l'**hyperthermie** ;\n- le **syndrome d'hyperventilation** ou dyspnée psychogène.\n\n[B] Les étiologies plus rares à connaître incluent également le pseudo-asthme cardiaque, la tamponnade, les états de choc, l'acidose métabolique, les hyperthermies, les sténoses trachéales, l'intoxication au CO et la pneumocystose.","keyPoints":["Dyspnée inspiratoire + cornage + tirage = orientation laryngotrachéale.","L'œdème de Quincke s'intègre souvent à un choc anaphylactique et menace par l'œdème de la glotte.","Chez l'enfant : corps étranger inhalé, épiglottite, laryngite sont les urgences laryngotrachéales à connaître.","Les signes radiographiques indirects orientent vers un corps étranger bronchique chez l'enfant.","Les causes neurologiques (bulbaires, polyradiculonévrite, myasthénie) sont des causes de dyspnée aiguë à ne pas négliger."],"pitfalls":["Examiner l'oropharynx d'un enfant suspect de corps étranger ou d'épiglottite, geste à éviter.","Sous-estimer la gravité d'une atteinte neuromusculaire ou d'un œdème de Quincke."],"src":"p. 442, 449"},{"id":"203-sec-09","title":"Orientation diagnostique devant une dyspnée aiguë","rank":"A","objectives":["203-obj-06","203-obj-14"],"content":"La démarche s'organise en cascade de questions cliniques simples (fig. 17.1 du référentiel) :\n\n1. **Signes de choc ?** Oui → la prise en charge du choc prime, la dyspnée passe au second plan. Non → poursuivre.\n2. **Dyspnée inspiratoire ?** Oui → cause laryngée (laisser le patient assis, éviter l'examen de l'oropharynx ; une dyspnée inspiratoire progressive évoque une cause néoplasique). Non → poursuivre.\n3. **Dyspnée expiratoire avec ronchi/sibilants ?** Oui → asthme, BPCO ou pseudo-asthme cardiaque. Non → poursuivre.\n4. **Crépitants ?** Oui → insuffisance ventriculaire gauche (attention au pseudo-asthme cardiaque et à l'OAP lésionnel du SDRA) ; si fièvre et syndrome de condensation ou toux, penser à la pneumopathie. Non → poursuivre.\n5. **Syndrome pleural ?** Oui → pneumothorax ou épanchement pleural. Non → poursuivre.\n6. **Dyspnée isolée**, sans autre orientation → évoquer une embolie pulmonaire (douleur inconstante), un sepsis sévère, une anémie ou une acidose métabolique ; par élimination, un syndrome d'hyperventilation ou une dyspnée psychogène.\n\n> Cas particulier : en cas d'atteinte neuromusculaire, la dyspnée est **tardive** et peut précéder de peu l'arrêt respiratoire — un piège classique de sous-estimation.","keyPoints":["L'arbre décisionnel part des signes de choc, puis du caractère inspiratoire, expiratoire, des crépitants et du syndrome pleural.","Devant un choc, la dyspnée s'efface derrière la prise en charge hémodynamique.","Dyspnée expiratoire + ronchi/sibilants = asthme, BPCO, pseudo-asthme cardiaque.","Crépitants = IVG, mais attention au pseudo-asthme cardiaque et au SDRA.","Dyspnée isolée sans orientation = penser EP, sepsis sévère, anémie, acidose, ou par élimination cause psychogène.","Une dyspnée d'origine neuromusculaire est tardive et de gravité sous-estimée."],"pitfalls":["Éliminer trop vite une insuffisance cardiaque gauche devant des crépitants qui peuvent être un pseudo-asthme cardiaque ou un SDRA.","Retarder le diagnostic d'une atteinte neuromusculaire car la dyspnée y est trompeusement tardive."],"src":"p. 449-450"},{"id":"203-sec-10","title":"Démarche diagnostique devant une dyspnée chronique","rank":"A","objectives":["203-obj-05"],"content":"Toute étiologie de dyspnée aiguë peut initialement évoluer sur un mode chronique ou subaigu ; comme pour la dyspnée aiguë, les causes les plus fréquentes de dyspnée chronique sont d'origine cardiopulmonaire.\n\nContrairement à la dyspnée aiguë, le bilan **peut se faire sans urgence**. Les principaux examens à discuter sont :\n- **NFP** : toujours éliminer une anémie avant d'engager des explorations plus poussées ;\n- **explorations fonctionnelles respiratoires (EFR)** avec gazométrie artérielle ;\n- **ECG** ;\n- **échocardiographie doppler** ;\n- **radiographie de thorax** ;\n- **épreuve d'effort** avec mesure des gaz respiratoires et de la consommation d'oxygène (± saturation à l'effort) : examen très informatif, il objective la gêne respiratoire de façon plus fiable et oriente vers une origine plutôt cardiaque ou pulmonaire ;\n- **scanner thoracique** pour l'étude du parenchyme pulmonaire ;\n- **cathétérisme cardiaque**, en particulier si une hypertension pulmonaire est suspectée.","keyPoints":["Toute cause de dyspnée aiguë peut évoluer sur un mode chronique.","Le bilan d'une dyspnée chronique n'est pas urgent, contrairement à la dyspnée aiguë.","Toujours éliminer une anémie en premier lieu (NFP).","L'épreuve d'effort avec mesure des gaz objective la gêne et oriente cardiaque vs pulmonaire.","Le scanner thoracique explore le parenchyme ; le cathétérisme cardiaque explore l'hémodynamique."],"pitfalls":["Multiplier les examens invasifs avant d'avoir éliminé une simple anémie."],"src":"p. 450"},{"id":"203-sec-11","title":"Étiologies cardiaques et pulmonaires de la dyspnée chronique","rank":"A","objectives":["203-obj-10"],"content":"**Étiologies cardiaques**, nombreuses, regroupant :\n- toutes les causes d'**insuffisance cardiaque** : cardiopathies valvulaires, ischémiques, cardiomyopathies dilatées primitives ou toxiques, insuffisance cardiaque à fonction systolique préservée, etc. ;\n- la **constriction péricardique**.\n\nL'examen clinique, l'ECG et la radiographie de thorax orientent le diagnostic. Le dosage du BNP/NT-proBNP peut aider (bien que moins validé qu'en situation aiguë) : un BNP strictement normal rend le diagnostic peu probable. En cas de suspicion, une **échocardiographie** doit rechercher une cardiopathie et des signes d'élévation des pressions intracardiaques.\n\n**Étiologies pulmonaires**, séparées selon le trouble ventilatoire :\n- **obstructif** : BPCO, asthme à dyspnée continue ;\n- **restrictif** : pneumopathies infiltrantes diffuses (infiltration diffuse de la charpente conjonctive du poumon, souvent des espaces alvéolaires, bronchioles et petits vaisseaux, avec fibrose collagène ou dépôts), pneumoconioses (inhalation de particules, ex. asbestose), séquelles pleurales post-tuberculeuses, paralysie phrénique, cyphoscoliose, obésité morbide.","keyPoints":["Les causes cardiaques de dyspnée chronique regroupent toutes les IC et la constriction péricardique.","Un BNP strictement normal rend une origine cardiaque chronique peu probable.","L'échocardiographie confirme la cardiopathie et les pressions de remplissage élevées.","Trouble ventilatoire obstructif : BPCO, asthme à dyspnée continue.","Trouble ventilatoire restrictif : PID, pneumoconioses, séquelles pleurales, paralysie phrénique, cyphoscoliose, obésité morbide."],"pitfalls":["Oublier la constriction péricardique parmi les causes cardiaques de dyspnée chronique."],"src":"p. 451"},{"id":"203-sec-12","title":"Hypertension artérielle pulmonaire et hypertension pulmonaire post-embolique","rank":"A","objectives":["203-obj-10"],"content":"**Hypertension artérielle pulmonaire (HTAP)** : ses principales formes sont l'**idiopathique** (anciennement primitive), la forme **familiale**, l'HTAP associée à une connectivité (le plus souvent sclérodermie), à un shunt intracardiaque, ou à une infection à VIH, et l'HTAP **d'origine toxique** (antécédent de prise d'anorexigènes, ex. dexfenfluramine).\n\nIl s'agit d'une hypertension pulmonaire **précapillaire**, définie au cathétérisme cardiaque droit par une **PAPm > 25 mmHg au repos** (ou **> 30 mmHg à l'effort**) associée à une **pression capillaire moyenne < 15 mmHg**.\n\n> Le terme d'HTAP doit être réservé aux hypertensions pulmonaires avec élévation isolée de la pression artérielle pulmonaire. Dans les autres cas (cardiopathie gauche, maladie respiratoire, postembolique), on parle d'**hypertension pulmonaire**.\n\nCliniquement : dyspnée pouvant toucher tout âge, examen cardiopulmonaire et radiographie souvent normaux. Le diagnostic est **évoqué à l'échocardiographie** (élévation des pressions pulmonaires) et **confirmé par le cathétérisme cardiaque droit**. Le pronostic, bien que réservé, s'est amélioré grâce aux antagonistes des récepteurs de l'endothéline (bosentan).\n\n**Hypertension pulmonaire post-embolique** : complication grave de la maladie thromboembolique, faisant suite à un ou plusieurs épisodes d'embolie pulmonaire, avec persistance d'une hypertension pulmonaire précapillaire.","keyPoints":["HTAP idiopathique, familiale, associée (connectivité, shunt, VIH) ou toxique sont les principales formes.","HTAP = hypertension précapillaire : PAPm > 25 mmHg au repos (ou > 30 à l'effort) et pression capillaire < 15 mmHg.","Diagnostic évoqué en échocardiographie, confirmé par cathétérisme cardiaque droit.","L'hypertension pulmonaire post-embolique complique une ou plusieurs EP antérieures."],"pitfalls":["Employer le terme d'HTAP pour une hypertension pulmonaire post-capillaire liée à une cardiopathie gauche."],"src":"p. 451-452"},{"id":"203-sec-13","title":"Autres causes de dyspnée chronique et situations particulières","rank":"A","objectives":["203-obj-10"],"content":"D'autres causes de dyspnée chronique doivent être connues :\n- **obstacles sur les voies aériennes supérieures** : tumeur ORL, corps étranger méconnu, tumeurs trachéales ou médiastinales ;\n- **anémie** — à toujours évoquer ;\n- **acidose métabolique** ;\n- **causes neuromusculaires** (myopathie) ;\n- **syndrome d'hyperventilation** ou dyspnée psychogène ;\n- **pathologies du transport de l'oxygène** : sulfhémoglobinémie, méthémoglobinémie ;\n- **intoxication au monoxyde de carbone** ;\n- **syndrome de platypnée-orthodéoxie** : dyspnée en orthostatisme associée à une désaturation, faisant rechercher un shunt droite-gauche (foramen ovale perméable).\n\n> Point de sémiologie générale : les causes **extrathoraciques** (acidose, anémie) entraînent davantage une **polypnée** (augmentation de la fréquence respiratoire, compensatrice) qu'une véritable dyspnée ressentie.\n\nChez l'enfant, les étiologies les plus fréquentes de dyspnée aiguë restent l'inhalation de corps étranger, la laryngite et l'épiglottite ; la gravité des causes laryngées (œdème de Quincke) et neuromusculaires (polyradiculonévrite) est fréquemment sous-estimée.","keyPoints":["Toujours penser à l'anémie devant une dyspnée chronique inexpliquée.","Le syndrome de platypnée-orthodéoxie fait rechercher un shunt droite-gauche (foramen ovale perméable).","Les causes extrathoraciques donnent plutôt une polypnée qu'une dyspnée vraie.","Chez l'enfant, corps étranger, laryngite et épiglottite dominent les urgences respiratoires aiguës."],"pitfalls":["Sous-estimer la gravité d'un œdème de Quincke ou d'une polyradiculonévrite chez l'enfant ou l'adulte."],"src":"p. 452"}],"essentials":[{"text":"La dyspnée est une sensation subjective d'inconfort respiratoire, ressentie pour un niveau d'activité habituellement bien toléré.","rank":"A","src":"p. 442","id":"203-ess-01"},{"text":"Dyspnée et insuffisance respiratoire ne sont pas synonymes : l'une peut exister sans l'autre.","rank":"A","src":"p. 443","id":"203-ess-02"},{"text":"On distingue dyspnée aiguë (heures à jours) et dyspnée chronique (semaines à mois).","rank":"A","src":"p. 443","id":"203-ess-03"},{"text":"L'orthopnée est une dyspnée de décubitus ; la platypnée, une dyspnée d'orthostatisme.","rank":"A","src":"p. 443","id":"203-ess-04"},{"text":"La classification NYHA (stades I à IV) est l'échelle de référence de la dyspnée chronique en cardiologie.","rank":"A","src":"p. 443","id":"203-ess-05"},{"text":"L'échelle MRC (stades 0 à 4) est l'équivalent pneumologique de la NYHA.","rank":"A","src":"p. 443","id":"203-ess-06"},{"text":"L'EVA et l'échelle de Borg graduent l'intensité d'une dyspnée aiguë.","rank":"A","src":"p. 443","id":"203-ess-07"},{"text":"La dyspnée de Kussmaul évoque une acidose métabolique.","rank":"A","src":"p. 444","id":"203-ess-08"},{"text":"La dyspnée de Cheyne-Stokes évoque une insuffisance cardiaque grave d'origine centrale.","rank":"A","src":"p. 444","id":"203-ess-09"},{"text":"Une SpO2 < 90 % impose l'administration d'oxygène.","rank":"A","src":"p. 444","id":"203-ess-10"},{"text":"Les signes de gravité respiratoire associent signes de lutte, signes de mauvaise tolérance (cyanose, tachycardie > 120/min, choc, SpO2 < 90 %) et signes neurologiques.","rank":"A","src":"p. 444","id":"203-ess-11"},{"text":"La gazométrie artérielle évalue la gravité (hypoxémie, hypercapnie) d'une dyspnée aiguë et peut orienter le diagnostic.","rank":"A","src":"p. 444","id":"203-ess-12"},{"text":"Un BNP < 100 pg/mL ou un NT-proBNP < 300 pg/mL rend une insuffisance cardiaque peu probable devant une dyspnée aiguë.","rank":"A","src":"p. 445","id":"203-ess-13"},{"text":"Les seuils de NT-proBNP recommandés par l'ESC 2021 augmentent avec l'âge (450, 900 puis 1 800 pg/mL).","rank":"B","src":"p. 445","id":"203-ess-14"},{"text":"Un taux de D-dimères bas permet d'exclure une embolie pulmonaire si la probabilité clinique est faible ou intermédiaire.","rank":"A","src":"p. 445","id":"203-ess-15"},{"text":"L'œdème aigu du poumon est la cause cardiaque la plus fréquente de dyspnée aiguë.","rank":"A","src":"p. 446","id":"203-ess-16"},{"text":"Le pseudo-asthme cardiaque est un équivalent d'OAP à forme bronchospastique, source de confusion avec l'asthme.","rank":"B","src":"p. 447","id":"203-ess-17"},{"text":"La tamponnade associe orthopnée, auscultation pulmonaire normale, assourdissement des bruits du cœur, turgescence jugulaire et pouls paradoxal.","rank":"B","src":"p. 447","id":"203-ess-18"},{"text":"Dans le choc cardiogénique, la dyspnée n'est pas au premier plan, contrairement au collapsus.","rank":"B","src":"p. 447","id":"203-ess-19"},{"text":"L'embolie pulmonaire donne le plus souvent une auscultation normale et une gazométrie en effet shunt (hypoxie-hypocapnie).","rank":"A","src":"p. 447","id":"203-ess-20"},{"text":"L'asthme aigu grave se reconnaît à un thorax bloqué, la disparition des sibilants et du murmure vésiculaire : c'est une urgence vitale.","rank":"A","src":"p. 447","id":"203-ess-21"},{"text":"L'exacerbation de BPCO se définit par la majoration de la dyspnée, de la toux ou des expectorations, avec gravité si polypnée > 25/min.","rank":"A","src":"p. 448","id":"203-ess-22"},{"text":"Le SDRA est une défaillance pulmonaire aiguë sévère par atteinte de la perméabilité alvéolocapillaire, à traiter en réanimation.","rank":"A","src":"p. 448","id":"203-ess-23"},{"text":"Le pneumothorax associe abolition du murmure vésiculaire et des vibrations vocales, tympanisme et hyperclarté radiographique.","rank":"A","src":"p. 448","id":"203-ess-24"},{"text":"Une dyspnée inspiratoire avec cornage et tirage oriente vers une cause laryngotrachéale.","rank":"A","src":"p. 449","id":"203-ess-25"},{"text":"L'œdème de Quincke menace par l'œdème de la glotte, souvent lors d'un choc anaphylactique.","rank":"A","src":"p. 449","id":"203-ess-26"},{"text":"Chez l'enfant, corps étranger inhalé, épiglottite et laryngite dominent les urgences laryngotrachéales.","rank":"A","src":"p. 449","id":"203-ess-27"},{"text":"Une dyspnée isolée sans orientation doit faire rechercher une embolie pulmonaire, un sepsis sévère, une anémie ou une acidose métabolique.","rank":"A","src":"p. 449","id":"203-ess-28"},{"text":"Devant un état de choc, la prise en charge du choc prime sur l'analyse de la dyspnée.","rank":"A","src":"p. 449","id":"203-ess-29"},{"text":"Dans les atteintes neuromusculaires, la dyspnée est tardive et peut précéder de peu l'arrêt respiratoire.","rank":"A","src":"p. 449","id":"203-ess-30"},{"text":"Devant une dyspnée chronique, il faut toujours éliminer une anémie avant des explorations plus poussées.","rank":"A","src":"p. 450","id":"203-ess-31"},{"text":"L'épreuve d'effort avec mesure des gaz respiratoires objective la gêne et oriente vers une origine cardiaque ou pulmonaire.","rank":"A","src":"p. 450","id":"203-ess-32"},{"text":"Les principales causes cardiaques de dyspnée chronique sont les cardiopathies (valvulaires, ischémiques, cardiomyopathies) et la constriction péricardique.","rank":"A","src":"p. 451","id":"203-ess-33"},{"text":"Un BNP strictement normal rend peu probable une origine cardiaque à une dyspnée chronique.","rank":"A","src":"p. 451","id":"203-ess-34"},{"text":"L'hypertension artérielle pulmonaire est précapillaire : PAPm > 25 mmHg au repos (ou > 30 à l'effort) et pression capillaire < 15 mmHg.","rank":"A","src":"p. 451","id":"203-ess-35"},{"text":"Le diagnostic d'HTAP est évoqué à l'échocardiographie et confirmé par le cathétérisme cardiaque droit.","rank":"A","src":"p. 451","id":"203-ess-36"},{"text":"L'hypertension pulmonaire post-embolique complique un ou plusieurs épisodes d'embolie pulmonaire.","rank":"B","src":"p. 452","id":"203-ess-37"},{"text":"Le syndrome de platypnée-orthodéoxie fait rechercher un shunt droite-gauche (foramen ovale perméable).","rank":"B","src":"p. 452","id":"203-ess-38"},{"text":"Les causes extrathoraciques (anémie, acidose) donnent davantage une polypnée qu'une dyspnée vraie.","rank":"A","src":"p. 452","id":"203-ess-39"},{"text":"Les étiologies les plus fréquentes de dyspnée aiguë chez l'adulte sont l'OAP, l'embolie pulmonaire et la décompensation d'une pathologie respiratoire chronique.","rank":"A","src":"p. 453","id":"203-ess-40"}],"numbers":[{"label":"NYHA stade II — seuil d'escaliers","value":"dyspnée pour la montée de plus de 2 étages","rank":"A","src":"p. 443","id":"203-num-01"},{"label":"NYHA stade III — seuil d'escaliers","value":"dyspnée pour la montée de moins de 2 étages","rank":"A","src":"p. 443","id":"203-num-02"},{"label":"Échelle MRC — nombre de stades","value":"5 stades (0 à 4)","rank":"A","src":"p. 443","id":"203-num-03"},{"label":"MRC stade 3","value":"arrêt nécessaire après environ 100 m de marche","rank":"A","src":"p. 443","id":"203-num-04"},{"label":"Échelle visuelle analogique (EVA) de dyspnée","value":"0 à 10 cm (0 = absence, 10 = maximale)","rank":"A","src":"p. 443","id":"203-num-05"},{"label":"Échelle de Borg","value":"0 à 10 (0 = nulle, 10 = maximale)","rank":"A","src":"p. 443","id":"203-num-06"},{"label":"Tachypnée/polypnée","value":"fréquence respiratoire > 20 cycles/min","rank":"A","src":"p. 444","id":"203-num-07"},{"label":"Bradypnée","value":"fréquence respiratoire < 10 cycles/min","rank":"A","src":"p. 444","id":"203-num-08"},{"label":"Tachycardie, signe de gravité de la dyspnée aiguë","value":"> 120/min","rank":"A","src":"p. 444","id":"203-num-09"},{"label":"SpO2, seuil de gravité / hypoxémie","value":"< 90 %","rank":"A","src":"p. 444","id":"203-num-10"},{"label":"BNP, seuil d'IC peu probable (dyspnée aiguë)","value":"< 100 pg/mL","rank":"A","src":"p. 445","id":"203-num-11"},{"label":"NT-proBNP, seuil d'IC peu probable (dyspnée aiguë)","value":"< 300 pg/mL","rank":"A","src":"p. 445","id":"203-num-12"},{"label":"NT-proBNP, seuil en faveur d'une IC (dyspnée aiguë)","value":"> 300 pg/mL","rank":"A","src":"p. 445","id":"203-num-13"},{"label":"NT-proBNP ESC 2021, seuil si âge < 55 ans","value":"> 450 pg/mL","rank":"B","src":"p. 445","id":"203-num-14"},{"label":"NT-proBNP ESC 2021, seuil si âge 55-75 ans","value":"> 900 pg/mL","rank":"B","src":"p. 445","id":"203-num-15"},{"label":"NT-proBNP ESC 2021, seuil si âge > 75 ans","value":"> 1 800 pg/mL","rank":"B","src":"p. 445","id":"203-num-16"},{"label":"D-dimères, seuil d'exclusion d'EP (probabilité faible/intermédiaire)","value":"< 500 pg/mL","rank":"A","src":"p. 445","id":"203-num-17"},{"label":"Polypnée, signe de gravité d'une exacerbation de BPCO","value":"> 25/min","rank":"A","src":"p. 448","id":"203-num-18"},{"label":"HTAP précapillaire, PAPm au repos","value":"> 25 mmHg","rank":"A","src":"p. 451","id":"203-num-19"},{"label":"HTAP précapillaire, PAPm à l'effort","value":"> 30 mmHg","rank":"A","src":"p. 451","id":"203-num-20"},{"label":"HTAP précapillaire, pression capillaire moyenne","value":"< 15 mmHg","rank":"A","src":"p. 451","id":"203-num-21"},{"label":"Délai d'installation d'une dyspnée aiguë","value":"quelques heures à quelques jours","rank":"A","src":"p. 443","id":"203-num-22"},{"label":"Délai d'installation d'une dyspnée chronique","value":"quelques semaines à quelques mois","rank":"A","src":"p. 443","id":"203-num-23"},{"label":"NYHA — nombre de stades","value":"4 stades (I à IV)","rank":"A","src":"p. 443","id":"203-num-24"},{"label":"MRC stade 4","value":"empêche de sortir du domicile, ou survient à l'habillage","rank":"A","src":"p. 443","id":"203-num-25"}],"mnemonics":[{"title":"Causes cardiaques de dyspnée aiguë","mnemonic":"« Oups, Pierre Tombe, Tremble, Collabe »","expansion":"- **O**ups → **O**AP\n- **P**ierre → **P**seudo-asthme cardiaque\n- **T**ombe → **T**amponnade\n- **T**remble → **T**roubles du rythme mal tolérés\n- **C**ollabe → **C**hoc cardiogénique","rank":"A","src":"p. 446-447","id":"203-mn-01"},{"title":"Causes pulmonaires et pleurales de dyspnée aiguë","mnemonic":"« As-tu Bu Pas Ses Anciens Étés Tranquilles ? »","expansion":"- **As**-tu → **A**sthme (crise)\n- **B**u → **B**PCO (exacerbation)\n- **P**as → **P**neumopathie infectieuse\n- **S**es → **S**DRA\n- **A**nciens → **A**télectasies\n- **É**tés → **É**tiologies pleurales (pneumothorax, épanchement)\n- **T**ranquilles → **T**raumatismes du thorax","rank":"A","src":"p. 447-449","id":"203-mn-02"},{"title":"Étiologies laryngotrachéales de dyspnée aiguë","mnemonic":"« Cet Enfant Tousse, Quincke ! »","expansion":"- **C**et → **C**orps étranger inhalé\n- **E**nfant → **E**nfant : causes infectieuses (épiglottite, laryngite)\n- **T**ousse → **T**rachéales : sténose, granulome post-intubation\n- **Q**uincke → **Q**uincke (œdème de la glotte)","rank":"A","src":"p. 449","id":"203-mn-03"},{"title":"Examens complémentaires de 1re intention devant une dyspnée aiguë","mnemonic":"« GERB »","expansion":"- **G** → **G**azométrie artérielle\n- **E** → **E**CG\n- **R** → **R**adiographie de thorax\n- **B** → **B**ilan biologique (NFP, iono, glycémie, BNP/NT-proBNP, D-dimères)","rank":"A","src":"p. 444-445","id":"203-mn-04"},{"title":"Autres étiologies (non cardio-pulmonaires) de dyspnée aiguë","mnemonic":"« Chaque Acidose Neurologique Cache Anémie, Hyperthermie, Psychose »","expansion":"- **Ch**aque → **Ch**oc (états de choc)\n- **A**cidose → **A**cidose métabolique\n- **N**eurologique → **N**eurologique (bulbaire, polyradiculonévrite, myasthénie)\n- **C**ache → **C**O (intoxication au monoxyde de carbone)\n- **A**némie → **A**némie aiguë\n- **H**yperthermie → **H**yperthermie\n- **P**sychose → **P**sychogène (syndrome d'hyperventilation)","rank":"A","src":"p. 449","id":"203-mn-05"},{"title":"Formes de l'hypertension artérielle pulmonaire","mnemonic":"« Isabelle Fume Chaque Soir Volontiers, Toxique ! »","expansion":"- **I**sabelle → **I**diopathique\n- **F**ume → **F**amiliale\n- **C**haque → **C**onnectivité (sclérodermie)\n- **S**oir → **S**hunt intracardiaque\n- **V**olontiers → **V**IH\n- **T**oxique → **T**oxique (anorexigènes)","rank":"A","src":"p. 451","id":"203-mn-06"},{"title":"Causes pulmonaires restrictives de dyspnée chronique","mnemonic":"« Papa Porte Sa Petite Cyphose Obèse »","expansion":"- **Pa**pa → **P**neumopathies infiltrantes diffuses\n- **P**orte → **P**neumoconioses\n- **S**a → **S**équelles pleurales post-tuberculeuses\n- **P**etite → **P**aralysie phrénique\n- **Cyphose** → **Cyphose**coliose\n- **Obèse** → **Obèse**ité morbide","rank":"B","src":"p. 451","id":"203-mn-07"}]},"questions":[{"id":"203-qcm-001","type":"QRM","rank":"A","objective":"203-obj-01","tags":["définition"],"difficulty":1,"stem":"Concernant la définition et le caractère temporel de la dyspnée, quelles propositions sont exactes ?","options":[{"t":"La dyspnée est une sensation subjective, non mesurable directement par l'examinateur.","ok":true,"why":"C'est un symptôme, donc une perception rapportée par le patient, et non un signe objectif."},{"t":"Elle est toujours synonyme d'insuffisance respiratoire.","ok":false,"why":"Les deux notions sont dissociables : une dyspnée peut exister sans IR (anémie aiguë) et une IR peut survenir sans dyspnée (coma)."},{"t":"Une dyspnée aiguë s'installe en quelques heures à quelques jours.","ok":true,"why":"C'est la définition temporelle retenue pour le caractère aigu."},{"t":"Une dyspnée chronique s'installe elle aussi en quelques heures à quelques jours.","ok":false,"why":"La dyspnée chronique évolue sur quelques semaines à quelques mois, à la différence de la forme aiguë."},{"t":"La dyspnée ne peut avoir qu'une origine cardiologique ou pneumologique.","ok":false,"why":"Ses causes sont multiples : ORL, pneumologiques, cardiologiques et neurologiques."}],"explanation":"La dyspnée est un symptôme subjectif, distinct de l'insuffisance respiratoire, dont les causes sont plurisystémiques ; seul le délai d'installation distingue formes aiguë et chronique.","src":"p. 442-443"},{"id":"203-qcm-002","type":"QRM","rank":"A","objective":"203-obj-02","tags":["clinique"],"difficulty":1,"stem":"À propos de l'interrogatoire d'un patient dyspnéique, quelles affirmations sont exactes ?","options":[{"t":"L'orthopnée correspond à une dyspnée survenant ou majorée en décubitus.","ok":true,"why":"L'orthopnée est définie comme une dyspnée de décubitus."},{"t":"La platypnée est une dyspnée majorée en décubitus.","ok":false,"why":"C'est l'inverse : la platypnée est une dyspnée d'orthostatisme."},{"t":"L'interrogatoire apprécie d'abord le terrain : antécédents, comorbidités, traitements en cours.","ok":true,"why":"C'est la première étape de l'analyse sémiologique avant de caractériser la dyspnée elle-même."},{"t":"Un facteur déclenchant saisonnier, climatique ou toxique n'apporte aucune orientation diagnostique.","ok":false,"why":"Ces circonstances de survenue sont au contraire recherchées car elles orientent l'étiologie."},{"t":"L'intensité de la dyspnée chronique s'évalue classiquement par la classification NYHA.","ok":true,"why":"La NYHA est la classification la plus utilisée pour la dyspnée chronique, notamment en cardiologie."}],"explanation":"L'interrogatoire structuré (terrain, mode d'installation, circonstances, échelle de sévérité) est la base de l'analyse sémiologique d'une dyspnée, qu'elle soit aiguë ou chronique.","src":"p. 443"},{"id":"203-qru-001","type":"QRU","rank":"A","objective":"203-obj-02","tags":["clinique"],"difficulty":1,"stem":"Un patient insuffisant cardiaque décrit une dyspnée uniquement lors d'une marche rapide, en côte, ou à la montée de plus de deux étages, sans aucune gêne pour les efforts plus légers de la vie courante. À quel stade de la classification NYHA correspond cette description ?","options":[{"t":"Stade I","ok":false,"why":"Le stade I correspond à l'absence de gêne pour les efforts habituels."},{"t":"Stade II","ok":true,"why":"Le stade II NYHA correspond à une dyspnée pour des efforts importants habituels (marche rapide, côte, plus de 2 étages)."},{"t":"Stade III","ok":false,"why":"Le stade III correspond à une dyspnée pour des efforts peu intenses (marche à plat, moins de 2 étages)."},{"t":"Stade IV","ok":false,"why":"Le stade IV correspond à une dyspnée permanente, de repos ou pour des efforts minimes."},{"t":"Cette description n'est pas cotable par la NYHA.","ok":false,"why":"La NYHA permet précisément de coter ce type de description en 4 stades."}],"explanation":"La NYHA distingue 4 stades croissants de gêne fonctionnelle ; ici l'atteinte se limite aux efforts importants, ce qui correspond au stade II.","src":"p. 443"},{"id":"203-qcm-003","type":"QRM","rank":"A","objective":"203-obj-02","tags":["diagnostic"],"difficulty":2,"stem":"Concernant les échelles d'évaluation de la dyspnée, quelles propositions sont exactes ?","options":[{"t":"L'échelle MRC comporte 5 stades, cotés de 0 à 4.","ok":true,"why":"L'échelle MRC va du stade 0 au stade 4."},{"t":"Le stade 3 de l'échelle MRC correspond à un arrêt nécessaire après environ 100 mètres de marche.","ok":true,"why":"C'est la définition retenue pour ce stade."},{"t":"L'échelle MRC est préférentiellement utilisée en cardiologie, la NYHA en pneumologie.","ok":false,"why":"C'est l'inverse : la NYHA est la référence en cardiologie, la MRC est utilisée en pneumologie."},{"t":"Le stade 4 de la MRC empêche de sortir du domicile ou survient à l'habillage.","ok":true,"why":"C'est la définition du stade le plus sévère de la MRC."},{"t":"L'échelle de Borg est réservée à l'évaluation de la dyspnée chronique.","ok":false,"why":"L'échelle de Borg, comme l'EVA, sert surtout à évaluer l'intensité d'une dyspnée aiguë (ou après un exercice déterminé)."}],"explanation":"La MRC (0-4) est l'équivalent pneumologique de la NYHA (I-IV) pour la dyspnée chronique ; EVA et Borg évaluent plutôt la dyspnée aiguë.","src":"p. 443","trap":"Ne pas inverser les champs d'usage préférentiels de la NYHA (cardiologie) et de la MRC (pneumologie)."},{"id":"203-qru-002","type":"QRU","rank":"A","objective":"203-obj-02","tags":["clinique"],"difficulty":1,"stem":"Quel outil, gradué de 0 à 10 cm, permet d'évaluer l'intensité d'une dyspnée aiguë ?","options":[{"t":"La classification NYHA","ok":false,"why":"La NYHA (stades I à IV) évalue la dyspnée chronique, pas une échelle graduée en cm."},{"t":"L'échelle MRC","ok":false,"why":"La MRC est une échelle en stades (0 à 4), utilisée en pneumologie pour la dyspnée chronique."},{"t":"L'échelle visuelle analogique (EVA)","ok":true,"why":"L'EVA est une échelle de 10 cm, de 0 (absence de dyspnée) à 10 (dyspnée maximale)."},{"t":"Le score de Genève","ok":false,"why":"Le score de Genève évalue la probabilité clinique d'embolie pulmonaire, pas l'intensité d'une dyspnée."},{"t":"Le nombre d'oreillers utilisés la nuit","ok":false,"why":"C'est un indicateur indirect de l'orthopnée, pas une échelle graduée de 0 à 10."}],"explanation":"L'EVA (0 à 10 cm) et l'échelle de Borg (0 à 10) sont les outils d'évaluation de l'intensité de la dyspnée aiguë.","src":"p. 443"},{"id":"203-qcm-004","type":"QRM","rank":"A","objective":"203-obj-04","tags":["urgence","clinique"],"difficulty":2,"stem":"Un patient de 54 ans est admis pour une dyspnée aiguë. Il présente un tirage sus-sternal, des sueurs et une fréquence cardiaque à 130/min. Parmi les éléments suivants, lesquels doivent être recherchés comme signes de gravité ?","options":[{"t":"Une SpO2 < 90 %.","ok":true,"why":"Une SpO2 inférieure à 90 % traduit une hypoxémie et fait partie des signes de gravité."},{"t":"Une fréquence cardiaque > 120/min.","ok":true,"why":"La tachycardie au-delà de 120/min est un signe de gravité de la dyspnée aiguë."},{"t":"Un astérixis.","ok":true,"why":"L'astérixis traduit un retentissement neurologique (encéphalopathie respiratoire), signe de gravité."},{"t":"Un tympanisme à la percussion.","ok":false,"why":"Le tympanisme oriente vers un pneumothorax, ce n'est pas en soi un signe de gravité générique de la dyspnée."},{"t":"Un balancement thoraco-abdominal.","ok":true,"why":"C'est un signe de mise en jeu des muscles respiratoires accessoires, donc un signe de gravité."}],"explanation":"Les signes de gravité d'une dyspnée aiguë associent la mise en jeu des muscles accessoires, les signes hémodynamiques (tachycardie > 120/min, SpO2 < 90 %, marbrures) et le retentissement neurologique (astérixis, agitation, somnolence, coma) ; ils imposent une décision thérapeutique immédiate.","src":"p. 444"},{"id":"203-qru-003","type":"QRU","rank":"A","objective":"203-obj-02","tags":["clinique"],"difficulty":2,"stem":"Quel type de dyspnée, caractérisé par une alternance inspiration - pause - expiration - pause, est classiquement associé à une acidose métabolique ?","options":[{"t":"Dyspnée de Cheyne-Stokes","ok":false,"why":"Le Cheyne-Stokes correspond à une polypnée croissante puis décroissante entrecoupée d'apnées, d'origine centrale."},{"t":"Dyspnée de Kussmaul","ok":true,"why":"La dyspnée de Kussmaul, avec cette alternance en 4 temps, est typique de l'acidose métabolique."},{"t":"Platypnée","ok":false,"why":"La platypnée est une dyspnée d'orthostatisme, sans rapport avec ce rythme respiratoire particulier."},{"t":"Orthopnée","ok":false,"why":"L'orthopnée est une dyspnée de décubitus, pas un trouble du rythme respiratoire."},{"t":"Polypnée superficielle isolée","ok":false,"why":"Ce terme ne décrit pas l'alternance en 4 temps caractéristique de Kussmaul."}],"explanation":"La dyspnée de Kussmaul (inspiration-pause-expiration-pause) signe classiquement une acidose métabolique, à distinguer du Cheyne-Stokes vu dans l'insuffisance cardiaque grave.","src":"p. 444"},{"id":"203-qcm-005","type":"QRM","rank":"A","objective":"203-obj-02","tags":["clinique"],"difficulty":2,"stem":"Concernant la dyspnée de Cheyne-Stokes, quelles propositions sont exactes ?","options":[{"t":"Elle associe des phases de polypnée croissante puis décroissante entrecoupées de périodes d'apnée.","ok":true,"why":"C'est la définition même de ce rythme respiratoire particulier."},{"t":"Elle témoigne d'une origine centrale, par bas débit au niveau des centres respiratoires ou du tronc cérébral.","ok":true,"why":"Le mécanisme évoqué est un bas débit cérébral affectant la commande respiratoire centrale."},{"t":"Elle est typique de l'acidose métabolique.","ok":false,"why":"C'est la dyspnée de Kussmaul qui est typique de l'acidose métabolique."},{"t":"Elle peut se voir au cours d'une insuffisance cardiaque grave.","ok":true,"why":"C'est le contexte clinique cité pour ce rythme respiratoire."},{"t":"Elle correspond à une hyperpnée isolée, sans anomalie du rythme respiratoire.","ok":false,"why":"Il s'agit au contraire d'une anomalie du rythme (alternance de phases), pas d'une simple hyperpnée."}],"explanation":"Le Cheyne-Stokes (polypnée croissante-décroissante entrecoupée d'apnées) traduit une origine centrale, observée dans l'insuffisance cardiaque grave, à ne pas confondre avec le Kussmaul de l'acidose métabolique.","src":"p. 444"},{"id":"203-qcm-006","type":"QRM","rank":"A","objective":"203-obj-07","tags":["paraclinique"],"difficulty":1,"stem":"Devant une dyspnée aiguë, quels examens complémentaires sont recommandés en 1re intention ?","options":[{"t":"La gazométrie artérielle.","ok":true,"why":"Elle apprécie la gravité (hypoxémie, hypercapnie) et peut orienter l'étiologie."},{"t":"L'électrocardiogramme.","ok":true,"why":"Il recherche une embolie pulmonaire, une coronaropathie ou un trouble du rythme."},{"t":"La radiographie de thorax.","ok":true,"why":"Elle recherche une anomalie pariétale, pleurale, parenchymateuse, médiastinale ou une cardiomégalie."},{"t":"La scintigraphie pulmonaire de ventilation/perfusion.","ok":false,"why":"Cet examen est proposé en 2e intention, selon l'orientation étiologique."},{"t":"Le cathétérisme cardiaque.","ok":false,"why":"Le cathétérisme cardiaque est un examen de 2e intention, pas de 1re intention."}],"explanation":"Les examens de 1re intention devant une dyspnée aiguë sont la gazométrie artérielle, l'ECG, la radiographie de thorax et un bilan biologique (NFP, ionogramme, glycémie, BNP/NT-proBNP, D-dimères).","src":"p. 444-445"},{"id":"203-qru-004","type":"QRU","rank":"A","objective":"203-obj-07","tags":["biologie"],"difficulty":2,"stem":"Devant une dyspnée aiguë, quel seuil de BNP rend le diagnostic d'insuffisance cardiaque peu probable ?","options":[{"t":"BNP < 50 pg/mL","ok":false,"why":"Ce seuil n'est pas celui retenu par le référentiel."},{"t":"BNP < 100 pg/mL","ok":true,"why":"Un BNP < 100 pg/mL (ou NT-proBNP < 300 pg/mL) rend le diagnostic d'insuffisance cardiaque peu probable devant une dyspnée aiguë."},{"t":"BNP < 300 pg/mL","ok":false,"why":"C'est le seuil retenu pour le NT-proBNP, pas pour le BNP."},{"t":"BNP < 500 pg/mL","ok":false,"why":"Ce seuil n'est pas celui retenu par le référentiel."},{"t":"BNP < 1000 pg/mL","ok":false,"why":"Ce seuil n'est pas celui retenu par le référentiel."}],"explanation":"Devant une dyspnée aiguë, un BNP < 100 pg/mL ou un NT-proBNP < 300 pg/mL rendent le diagnostic d'insuffisance cardiaque peu probable ; des valeurs supérieures sont en faveur d'une IC.","src":"p. 445"},{"id":"203-qcm-007","type":"QRM","rank":"B","objective":"203-obj-08","tags":["biologie"],"difficulty":3,"stem":"Concernant l'interprétation du NT-proBNP selon l'âge devant une dyspnée aiguë (seuils retenus par les recommandations ESC 2021), quelles propositions sont exactes ?","options":[{"t":"Avant 55 ans, le seuil retenu est > 450 pg/mL.","ok":true,"why":"C'est le seuil rapporté pour les patients de moins de 55 ans."},{"t":"Entre 55 et 75 ans, le seuil retenu est > 900 pg/mL.","ok":true,"why":"C'est le seuil rapporté pour cette tranche d'âge."},{"t":"Après 75 ans, le seuil retenu est > 1200 pg/mL.","ok":false,"why":"Le seuil rapporté après 75 ans est > 1 800 pg/mL, et non 1 200 pg/mL."},{"t":"Un NT-proBNP < 300 pg/mL, en situation aiguë, rend le diagnostic d'IC peu probable indépendamment de ces seuils ajustés à l'âge.","ok":true,"why":"C'est le seuil général (non ajusté à l'âge) mentionné en premier lieu par le référentiel."},{"t":"Ces seuils diminuent avec l'âge.","ok":false,"why":"Au contraire, les seuils augmentent avec l'âge (450 puis 900 puis 1 800 pg/mL)."}],"explanation":"Les seuils de NT-proBNP recommandés par l'ESC 2021 croissent avec l'âge (450 / 900 / 1 800 pg/mL), en complément du seuil général < 300 pg/mL utilisé en situation aiguë.","src":"p. 445","trap":"Ne pas confondre le seuil général < 300 pg/mL avec les seuils ajustés à l'âge, plus élevés."},{"id":"203-qcm-008","type":"QRM","rank":"B","objective":"203-obj-08","tags":["paraclinique"],"difficulty":2,"stem":"Selon l'orientation clinique initiale, quels examens peuvent être discutés en 2e intention devant une dyspnée aiguë ?","options":[{"t":"Écho-doppler veineux des membres inférieurs.","ok":true,"why":"Proposé en cas de suspicion d'embolie pulmonaire."},{"t":"Angioscanner pulmonaire.","ok":true,"why":"Proposé en cas de suspicion d'embolie pulmonaire."},{"t":"Épreuve d'effort métabolique.","ok":true,"why":"Cet examen fait partie des examens de 2e intention cités par le référentiel."},{"t":"Gazométrie artérielle.","ok":false,"why":"La gazométrie artérielle est un examen de 1re intention, pas de 2e intention."},{"t":"Échocardiographie doppler.","ok":true,"why":"L'échocardiographie fait partie des examens de 2e intention à discuter selon l'orientation."}],"explanation":"En 2e intention, selon l'orientation initiale, on discute écho-doppler veineux, angioscanner ou scintigraphie pulmonaire, échocardiographie doppler, EFR, cathétérisme cardiaque ou épreuve d'effort métabolique.","src":"p. 445"},{"id":"203-qcm-009","type":"QRM","rank":"A","objective":"203-obj-03","tags":["clinique","étiologie"],"difficulty":2,"stem":"Un patient de 70 ans, connu porteur d'une cardiopathie ischémique, présente une orthopnée brutale avec crépitants bilatéraux et une expectoration mousseuse rosée. Quels éléments sont en faveur du diagnostic d'œdème aigu du poumon ?","options":[{"t":"La présence d'un wheezing associé.","ok":true,"why":"Le wheezing fait partie du tableau clinique classique de l'OAP."},{"t":"Une cardiomégalie avec œdème alvéolaire à la radiographie de thorax.","ok":true,"why":"Ce sont les anomalies radiographiques typiques de l'OAP."},{"t":"Une fibrillation atriale rapide à l'ECG.","ok":true,"why":"La FA est un facteur déclenchant classique et une anomalie ECG fréquemment retrouvée."},{"t":"Une auscultation pulmonaire strictement normale.","ok":false,"why":"L'OAP se caractérise au contraire par des crépitants bilatéraux à l'auscultation."},{"t":"Une amélioration sous diurétique ou trinitrine intraveineuse.","ok":true,"why":"La réponse favorable à ce traitement est un argument en faveur du diagnostic d'OAP."}],"explanation":"L'OAP, cause cardiaque la plus fréquente de dyspnée aiguë, associe orthopnée, crépitants bilatéraux, expectoration rose saumonée, cardiomégalie avec œdème alvéolaire, anomalies ECG (dont la FA) et réponse au traitement diurétique/trinitrine.","src":"p. 446-447"},{"id":"203-qru-005","type":"QRU","rank":"B","objective":"203-obj-09","tags":["étiologie","pièges"],"difficulty":2,"stem":"Quelle étiologie cardiaque de dyspnée aiguë se caractérise par une orthopnée, une auscultation pulmonaire normale, une turgescence jugulaire et un pouls paradoxal ?","options":[{"t":"L'œdème aigu du poumon","ok":false,"why":"L'OAP s'accompagne au contraire de crépitants bilatéraux, pas d'une auscultation pulmonaire normale."},{"t":"Le pseudo-asthme cardiaque","ok":false,"why":"Le pseudo-asthme cardiaque associe orthopnée et sibilants, pas une auscultation pulmonaire normale."},{"t":"La tamponnade","ok":true,"why":"La tamponnade associe orthopnée, auscultation pulmonaire normale, turgescence jugulaire et pouls paradoxal."},{"t":"Le choc cardiogénique","ok":false,"why":"Dans le choc cardiogénique, la dyspnée n'est pas au premier plan ; le tableau est dominé par le collapsus."},{"t":"Un trouble du rythme supraventriculaire mal toléré","ok":false,"why":"Ce tableau ne comporte pas typiquement de turgescence jugulaire ni de pouls paradoxal."}],"explanation":"La tamponnade, complication d'une péricardite avec épanchement, associe orthopnée, auscultation pulmonaire normale, assourdissement des bruits du cœur, turgescence jugulaire et pouls paradoxal, dans un tableau de collapsus.","src":"p. 447","trap":"Une auscultation pulmonaire normale devant une dyspnée aiguë ne doit pas faire écarter une cause cardiaque : elle doit au contraire faire penser à la tamponnade."},{"id":"203-qcm-010","type":"QRM","rank":"A","objective":"203-obj-03","tags":["étiologie","diagnostic"],"difficulty":2,"stem":"Une femme de 45 ans, immobilisée plusieurs heures lors d'un vol long-courrier, présente une dyspnée brutale sans douleur thoracique. Quelles propositions concernant l'embolie pulmonaire sont exactes ?","options":[{"t":"L'absence de douleur thoracique n'élimine pas le diagnostic.","ok":true,"why":"La douleur thoracique, bien que fréquente, n'est pas constante au cours de l'embolie pulmonaire."},{"t":"L'auscultation cardio-pulmonaire est habituellement normale.","ok":true,"why":"Elle est souvent normale, sauf en cas de tachycardie associée."},{"t":"La gazométrie artérielle montre typiquement une hypoxie associée à une hypercapnie.","ok":false,"why":"La gazométrie retrouve un effet shunt, c'est-à-dire une hypoxie associée à une hypocapnie, et non une hypercapnie."},{"t":"Un contexte d'immobilisation prolongée est un facteur favorisant à rechercher systématiquement.","ok":true,"why":"L'alitement, les voyages de longue durée ou l'immobilisation sont des contextes favorisants classiques."},{"t":"La survenue est en règle très progressive, sur plusieurs semaines.","ok":false,"why":"La survenue est en règle très brutale, non progressive sur plusieurs semaines."}],"explanation":"L'embolie pulmonaire, très fréquente et de diagnostic souvent difficile, se manifeste par une dyspnée brutale, d'intensité variable, parfois isolée, avec une auscultation souvent normale et un effet shunt (hypoxie-hypocapnie) à la gazométrie.","src":"p. 447"},{"id":"203-qru-006","type":"QRU","rank":"A","objective":"203-obj-03","tags":["urgence","clinique"],"difficulty":2,"stem":"Quel signe clinique doit faire évoquer un asthme aigu grave plutôt qu'une simple crise d'asthme ?","options":[{"t":"La persistance de sibilants diffus bilatéraux.","ok":false,"why":"Dans l'asthme aigu grave, les sibilants disparaissent, contrairement à la crise d'asthme simple."},{"t":"Un foyer de crépitants localisé.","ok":false,"why":"Ce signe oriente plutôt vers une pneumopathie qu'un asthme aigu grave."},{"t":"Un silence auscultatoire avec disparition du murmure vésiculaire et des sibilants.","ok":true,"why":"Le thorax bloqué en inflation avec silence auscultatoire est un signe classique et trompeur d'asthme aigu grave, urgence vitale."},{"t":"Une expectoration purulente abondante.","ok":false,"why":"Ce signe oriente vers une surinfection bronchique, pas spécifiquement vers l'asthme aigu grave."},{"t":"Une turgescence jugulaire isolée.","ok":false,"why":"Ce signe n'est pas caractéristique de l'asthme aigu grave."}],"explanation":"L'asthme aigu grave, urgence vitale, se traduit par un thorax bloqué en inflation avec disparition des sibilants et du murmure vésiculaire, un pouls paradoxal possible et une élocution impossible — un silence auscultatoire trompeur car rassurant en apparence.","src":"p. 447-448","trap":"Le silence auscultatoire (disparition des sibilants) peut être faussement rassurant alors qu'il signe la gravité extrême."},{"id":"203-qcm-011","type":"QRM","rank":"A","objective":"203-obj-03","tags":["clinique","urgence"],"difficulty":2,"stem":"Un patient de 68 ans, BPCO connu et tabagique, consulte pour une majoration de sa dyspnée habituelle, de sa toux et de la purulence de ses expectorations depuis 3 jours. Quelles propositions sont exactes ?","options":[{"t":"La majoration de la dyspnée, de la toux ou de la purulence des expectorations définit l'exacerbation.","ok":true,"why":"C'est la définition de l'exacerbation de BPCO donnée par le référentiel."},{"t":"Une polypnée supérieure à 25/min est un signe de gravité à rechercher.","ok":true,"why":"Ce seuil de fréquence respiratoire fait partie des signes de gravité d'une exacerbation de BPCO."},{"t":"L'hippocratisme digital est un signe de gravité de l'épisode aigu.","ok":false,"why":"L'hippocratisme digital peut être présent chez le patient BPCO, mais ce n'est pas cité comme un signe de gravité de l'exacerbation elle-même."},{"t":"La désaturation et l'hypercapnie sont des signes de gravité à rechercher.","ok":true,"why":"Ces éléments, avec la cyanose, la défaillance hémodynamique et les signes neurologiques, définissent la gravité de l'exacerbation."},{"t":"L'exacerbation de BPCO ne survient jamais à l'occasion d'une surinfection bronchique.","ok":false,"why":"L'exacerbation survient au contraire souvent à l'occasion d'une surinfection bronchique."}],"explanation":"L'exacerbation de BPCO se définit par la majoration de la dyspnée, de la toux ou de la purulence des expectorations, souvent lors d'une surinfection ; sa gravité s'évalue sur la dyspnée de repos, la cyanose, la désaturation, une polypnée > 25/min, une défaillance hémodynamique, des signes neurologiques et l'hypercapnie.","src":"p. 447-448"},{"id":"203-qcm-012","type":"QRM","rank":"A","objective":"203-obj-03","tags":["clinique","étiologie"],"difficulty":2,"stem":"Concernant les étiologies pulmonaires et pleurales de dyspnée aiguë, quelles propositions sont exactes ?","options":[{"t":"La pneumopathie infectieuse associe fièvre, foyer de crépitants et opacité parenchymateuse systématisée à la radiographie.","ok":true,"why":"C'est le tableau typique décrit pour la pneumopathie infectieuse."},{"t":"Le SDRA correspond à un œdème pulmonaire lésionnel, à distinguer de l'œdème hémodynamique.","ok":true,"why":"Le SDRA se caractérise par une augmentation de la perméabilité alvéolocapillaire et un œdème lésionnel."},{"t":"Le SDRA peut se traiter en ambulatoire, sans hospitalisation en réanimation.","ok":false,"why":"Le SDRA, forme sévère avec mortalité élevée, nécessite un traitement en réanimation."},{"t":"Le pneumothorax se manifeste par une abolition des vibrations vocales et du murmure vésiculaire avec tympanisme.","ok":true,"why":"Ce sont les signes cliniques classiques du pneumothorax, avec hyperclarté à la radiographie."},{"t":"Les traumatismes thoraciques ne peuvent jamais se compliquer de pneumomédiastin.","ok":false,"why":"Les traumatismes thoraciques peuvent au contraire se compliquer d'hémopéricarde, de pneumothorax, de pneumomédiastin, d'hémothorax ou de volet thoracique."}],"explanation":"Pneumopathie (fièvre + crépitants + opacité systématisée), SDRA (œdème lésionnel grave nécessitant la réanimation) et pneumothorax (abolition MV/vibrations, tympanisme, hyperclarté) sont des étiologies pulmonaires/pleurales classiques de dyspnée aiguë.","src":"p. 448-449"},{"id":"203-qru-007","type":"QRU","rank":"A","objective":"203-obj-03","tags":["clinique"],"difficulty":1,"stem":"Une dyspnée inspiratoire associée à une bradypnée inspiratoire, un cornage et un tirage oriente en premier lieu vers quelle origine ?","options":[{"t":"Une origine laryngée ou trachéale.","ok":true,"why":"Les causes laryngotrachéales se traduisent typiquement par ce tableau de dyspnée inspiratoire."},{"t":"Une origine pleurale.","ok":false,"why":"Une origine pleurale se traduit plutôt par un syndrome pleural (abolition MV, tympanisme ou matité)."},{"t":"Une origine alvéolaire.","ok":false,"why":"Une atteinte alvéolaire se traduit surtout par des crépitants, pas par une dyspnée inspiratoire avec cornage."},{"t":"Une insuffisance cardiaque gauche.","ok":false,"why":"L'insuffisance cardiaque gauche se traduit typiquement par une orthopnée avec crépitants, pas par un cornage."},{"t":"Une atteinte neuromusculaire.","ok":false,"why":"Les causes neuromusculaires donnent une dyspnée le plus souvent tardive, sans cornage typique."}],"explanation":"Cornage, tirage et bradypnée inspiratoire orientent vers une cause laryngotrachéale ; une dysphonie associée renforce l'orientation laryngée.","src":"p. 449"},{"id":"203-qcm-013","type":"QRM","rank":"A","objective":"203-obj-06","tags":["diagnostic","pièges"],"difficulty":3,"stem":"Concernant la démarche d'orientation étiologique devant une dyspnée aiguë, quelles propositions sont exactes ?","options":[{"t":"La première question à se poser est la présence ou non de signes de choc.","ok":true,"why":"L'arbre décisionnel débute par la recherche de signes de choc, qui priment sur l'analyse de la dyspnée."},{"t":"Des crépitants orientent systématiquement et sans piège vers une insuffisance ventriculaire gauche.","ok":false,"why":"Les crépitants orientent vers l'IVG, mais il faut se méfier du pseudo-asthme cardiaque et de l'œdème lésionnel du SDRA, qui peuvent aussi donner des crépitants."},{"t":"Une dyspnée isolée sans autre orientation doit faire évoquer une embolie pulmonaire même sans douleur thoracique.","ok":true,"why":"La dyspnée isolée fait rechercher une embolie pulmonaire, un sepsis sévère, une anémie ou une acidose métabolique."},{"t":"En cas d'atteinte neuromusculaire, la dyspnée apparaît précocement, bien avant les autres signes.","ok":false,"why":"Au contraire, la dyspnée d'origine neuromusculaire est tardive et peut précéder de peu l'arrêt respiratoire."},{"t":"Un syndrome pleural oriente vers un pneumothorax ou un épanchement pleural.","ok":true,"why":"C'est l'étape suivante de la démarche en cas d'absence de crépitants."}],"explanation":"La démarche part des signes de choc, puis explore successivement le caractère inspiratoire, expiratoire, les crépitants et le syndrome pleural, avec deux pièges classiques : le pseudo-asthme cardiaque/SDRA masqués en crépitants, et la dyspnée neuromusculaire trompeusement tardive.","src":"p. 449-450","trap":"Des crépitants ne signent pas toujours une IVG ; une dyspnée neuromusculaire tardive est un piège de sous-estimation classique."},{"id":"203-qcm-014","type":"QRM","rank":"A","objective":"203-obj-10","tags":["étiologie"],"difficulty":2,"stem":"Concernant les étiologies de la dyspnée chronique, quelles propositions sont exactes ?","options":[{"t":"Toutes les causes d'insuffisance cardiaque (valvulaire, ischémique, cardiomyopathies) peuvent être en cause.","ok":true,"why":"Les étiologies cardiaques de dyspnée chronique regroupent toutes les causes d'IC."},{"t":"La constriction péricardique fait partie des étiologies cardiaques de dyspnée chronique.","ok":true,"why":"Elle est citée comme cause cardiaque à part entière, à côté des causes d'IC."},{"t":"Un trouble ventilatoire obstructif regroupe la BPCO et l'asthme à dyspnée continue.","ok":true,"why":"Ce sont les deux exemples cités de trouble ventilatoire obstructif chronique."},{"t":"Un trouble ventilatoire restrictif ne comprend que la cyphoscoliose.","ok":false,"why":"Le trouble restrictif regroupe aussi les pneumopathies infiltrantes diffuses, les pneumoconioses, les séquelles pleurales post-tuberculeuses, la paralysie phrénique et l'obésité morbide."},{"t":"Un BNP strictement normal rend une origine cardiaque chronique peu probable.","ok":true,"why":"Le dosage du BNP, moins validé qu'en aigu, peut aider : un taux strictement normal rend le diagnostic d'IC peu probable."}],"explanation":"Les étiologies cardiaques (toutes les IC + constriction péricardique) et pulmonaires (obstructives : BPCO, asthme ; restrictives : PID, pneumoconioses, séquelles pleurales, paralysie phrénique, cyphoscoliose, obésité) dominent la dyspnée chronique.","src":"p. 451"},{"id":"203-qcm-015","type":"QRM","rank":"A","objective":"203-obj-10","tags":["étiologie","paraclinique"],"difficulty":3,"stem":"Concernant l'hypertension artérielle pulmonaire (HTAP), quelles propositions sont exactes ?","options":[{"t":"Il s'agit d'une hypertension pulmonaire précapillaire.","ok":true,"why":"L'HTAP est définie comme une hypertension pulmonaire précapillaire."},{"t":"Elle est définie par une PAPm > 25 mmHg au repos, associée à une pression capillaire moyenne < 15 mmHg.","ok":true,"why":"Ce sont les critères hémodynamiques mesurés au cathétérisme cardiaque droit."},{"t":"Le diagnostic est confirmé par l'échocardiographie seule.","ok":false,"why":"Le diagnostic est évoqué à l'échocardiographie mais confirmé par le cathétérisme cardiaque droit."},{"t":"Les formes idiopathique, familiale, associée (connectivité, shunt, VIH) et toxique sont les principales causes.","ok":true,"why":"Ce sont les principales formes citées pour l'HTAP."},{"t":"Le pronostic s'est amélioré grâce aux antagonistes des récepteurs de l'endothéline.","ok":true,"why":"Le bosentan, antagoniste des récepteurs de l'endothéline, a amélioré le pronostic de cette pathologie."}],"explanation":"L'HTAP, hypertension pulmonaire précapillaire (PAPm > 25 mmHg au repos, pression capillaire < 15 mmHg), est évoquée à l'échocardiographie et confirmée par cathétérisme cardiaque droit ; son pronostic s'est amélioré avec les antagonistes des récepteurs de l'endothéline.","src":"p. 451-452"},{"id":"203-qroc-001","type":"QROC","rank":"A","objective":"203-obj-01","tags":["définition"],"difficulty":1,"question":"Donnez la définition de la dyspnée.","answer":"Sensation subjective d'inconfort ou de difficulté respiratoire, ressentie pour un niveau d'activité habituellement bien toléré.","accept":["gêne respiratoire subjective","inconfort respiratoire"],"keywords":["subjective","inconfort","activité"],"explanation":"La dyspnée est un symptôme, donc une perception rapportée par le patient, non un signe mesurable objectivement.","src":"p. 442"},{"id":"203-qroc-002","type":"QROC","rank":"A","objective":"203-obj-06","tags":["diagnostic","urgence"],"difficulty":1,"question":"Dans la démarche d'orientation devant une dyspnée aiguë, quelle question doit être posée en tout premier lieu, avant même de préciser le caractère inspiratoire ou expiratoire ?","answer":"La présence de signes de choc.","accept":["signes de choc","état de choc"],"keywords":["choc"],"explanation":"Si des signes de choc sont présents, leur prise en charge prime sur l'analyse fine de la dyspnée, qui passe au second plan.","src":"p. 449-450"},{"id":"203-qroc-003","type":"QROC","rank":"A","objective":"203-obj-02","tags":["clinique"],"difficulty":1,"question":"Quel est le seuil de fréquence respiratoire en dessous duquel on parle de bradypnée ?","answer":"Moins de 10 cycles par minute.","accept":["< 10/min","moins de 10 cycles/min"],"keywords":["10","cycles"],"explanation":"La bradypnée est définie par une fréquence respiratoire inférieure à 10 cycles/min, à l'opposé de la tachypnée/polypnée (> 20/min).","src":"p. 444"},{"id":"203-qroc-004","type":"QROC","rank":"A","objective":"203-obj-02","tags":["clinique"],"difficulty":1,"question":"Quel est le seuil de fréquence respiratoire au-delà duquel on parle de tachypnée ou polypnée ?","answer":"Plus de 20 cycles par minute.","accept":["> 20/min","plus de 20 cycles/min"],"keywords":["20","cycles"],"explanation":"La tachypnée (ou polypnée) est définie par une fréquence respiratoire supérieure à 20 cycles/min.","src":"p. 444"},{"id":"203-qroc-005","type":"QROC","rank":"A","objective":"203-obj-11","tags":["urgence"],"difficulty":2,"question":"Que doit entraîner, dans l'immédiat, la présence de signes de gravité au cours d'une dyspnée aiguë, quelle que soit son étiologie ?","answer":"Des décisions thérapeutiques immédiates.","accept":["prise en charge urgente","traitement immédiat"],"keywords":["immédiat","décision","thérapeutique"],"explanation":"Les signes de gravité identifiés à l'examen imposent une prise en charge thérapeutique sans délai, indépendamment de la recherche étiologique complète.","src":"p. 442-444"},{"id":"203-qroc-006","type":"QROC","rank":"A","objective":"203-obj-05","tags":["biologie","diagnostic"],"difficulty":1,"question":"Devant une dyspnée chronique, quel examen biologique de base doit être réalisé en priorité pour éliminer une anémie ?","answer":"Numération formule (plaquettaire).","accept":["NFS","numération formule sanguine","NFP"],"keywords":["numération","anémie"],"explanation":"L'élimination d'une anémie par la numération formule est la première étape avant d'engager des explorations plus poussées devant une dyspnée chronique.","src":"p. 450"},{"id":"203-qroc-007","type":"QROC","rank":"A","objective":"203-obj-10","tags":["étiologie"],"difficulty":2,"question":"Outre les différentes causes d'insuffisance cardiaque, quelle autre affection cardiaque doit être connue comme cause de dyspnée chronique ?","answer":"La constriction péricardique.","accept":["péricardite constrictive"],"keywords":["constriction","péricardique"],"explanation":"La constriction péricardique est citée comme cause cardiaque de dyspnée chronique, à côté de l'ensemble des cardiopathies responsables d'insuffisance cardiaque.","src":"p. 451"},{"id":"203-qroc-008","type":"QROC","rank":"A","objective":"203-obj-10","tags":["étiologie","paraclinique"],"difficulty":2,"question":"Citez deux exemples d'affections responsables d'un trouble ventilatoire de type restrictif pouvant causer une dyspnée chronique.","answer":"Pneumopathies infiltrantes diffuses et pneumoconioses.","accept":["PID et pneumoconiose","fibrose pulmonaire et asbestose"],"keywords":["restrictif","infiltrante"],"explanation":"Le trouble ventilatoire restrictif regroupe notamment les pneumopathies infiltrantes diffuses, les pneumoconioses (ex. asbestose), les séquelles pleurales post-tuberculeuses, la paralysie phrénique, la cyphoscoliose et l'obésité morbide.","src":"p. 451"},{"id":"203-qroc-009","type":"QROC","rank":"A","objective":"203-obj-16","tags":["imagerie","pédiatrie"],"difficulty":2,"question":"Chez l'enfant présentant une dyspnée aiguë, quelle étiologie la stratégie d'imagerie ciblée doit-elle rechercher en priorité, à travers des signes radiographiques indirects ?","answer":"L'inhalation d'un corps étranger bronchique.","accept":["corps étranger bronchique inhalé"],"keywords":["corps étranger","bronchique"],"explanation":"Chez l'enfant, une stratégie d'imagerie ciblée est nécessaire devant une dyspnée aiguë pour rechercher les signes radiographiques indirects d'un corps étranger bronchique inhalé.","src":"p. 442, 449"},{"id":"203-qroc-010","type":"QROC","rank":"A","objective":"203-obj-10","tags":["paraclinique","diagnostic"],"difficulty":2,"question":"Donnez la définition hémodynamique de l'hypertension artérielle pulmonaire (HTAP), mesurée au cathétérisme cardiaque droit.","answer":"PAPm > 25 mmHg au repos (ou > 30 mmHg à l'effort) avec une pression capillaire moyenne < 15 mmHg.","accept":["PAPm supérieure à 25 mmHg et pression capillaire basse"],"keywords":["25","15","précapillaire"],"explanation":"Cette définition hémodynamique précapillaire distingue l'HTAP des autres formes d'hypertension pulmonaire (postcapillaire ou associée à une maladie respiratoire).","src":"p. 451"},{"id":"203-qroc-011","type":"QROC","rank":"A","objective":"203-obj-03","tags":["biologie","diagnostic"],"difficulty":2,"question":"Quel type d'anomalie gazométrique est classiquement retrouvé au cours d'une embolie pulmonaire ?","answer":"Un effet shunt : hypoxie associée à une hypocapnie.","accept":["hypoxie-hypocapnie"],"keywords":["hypoxie","hypocapnie"],"explanation":"L'effet shunt de l'embolie pulmonaire associe une hypoxémie à une hypocapnie, du fait de l'hyperventilation réactionnelle.","src":"p. 447"},{"id":"203-qroc-012","type":"QROC","rank":"A","objective":"203-obj-10","tags":["traitement"],"difficulty":2,"question":"Quelle classe thérapeutique a permis d'améliorer récemment le pronostic de l'HTAP idiopathique ?","answer":"Les antagonistes des récepteurs de l'endothéline (ex. bosentan).","accept":["antagonistes de l'endothéline","bosentan"],"keywords":["endothéline","récepteurs"],"explanation":"L'émergence des antagonistes des récepteurs de l'endothéline, comme le bosentan, a nettement amélioré un pronostic auparavant réservé.","src":"p. 452"},{"id":"203-open-01","type":"OPEN","rank":"A","objective":"203-obj-02","tags":["clinique","urgence","paraclinique"],"difficulty":2,"prompt":"Un homme de 58 ans, sans antécédent connu, est amené aux urgences pour une dyspnée d'apparition brutale depuis deux heures. Décrivez la démarche clinique et paraclinique de 1re intention permettant de caractériser cette dyspnée, de rechercher des signes de gravité et d'orienter le diagnostic étiologique.","rubric":[{"point":"Caractériser la dyspnée : phase du cycle (inspiratoire/expiratoire), fréquence respiratoire (tachypnée > 20, bradypnée < 10), rythme (régulier, Kussmaul, Cheyne-Stokes), intensité","weight":2},{"point":"Rechercher des signes de gravité : mise en jeu des muscles accessoires, cyanose, sueurs, tachycardie > 120/min, marbrures, SpO2 < 90 %, signes neurologiques (astérixis, agitation, coma)","weight":2},{"point":"Examen orienté : auscultation et percussion pulmonaires, examen cardiovasculaire, ORL, thyroïdien, neuromusculaire","weight":2},{"point":"Examens de 1re intention : gazométrie artérielle, ECG, radiographie de thorax, bilan biologique (NFP, ionogramme, glycémie, BNP/NT-proBNP, D-dimères si suspicion d'embolie pulmonaire)","weight":2},{"point":"Décision immédiate en cas de gravité : administration d'oxygène si SpO2 < 90 %, sans attendre le résultat de la gazométrie","weight":1}],"model":"**Caractérisation clinique** : préciser le temps respiratoire concerné, mesurer la fréquence respiratoire, apprécier le rythme (régulier, Kussmaul évocateur d'acidose métabolique, Cheyne-Stokes évocateur d'IC grave) et l'intensité.\n\n**Signes de gravité** : tirage, battement des ailes du nez, balancement thoraco-abdominal, cyanose, sueurs, tachycardie > 120/min, marbrures, SpO2 < 90 %, astérixis, agitation ou somnolence. Leur présence impose une décision thérapeutique immédiate, notamment l'oxygénothérapie si SpO2 < 90 %.\n\n**Examen orienté** : auscultation (crépitants, sibilants, silence auscultatoire), percussion (matité, tympanisme), examen cardiovasculaire (signes d'IC, thrombose veineuse), ORL, thyroïdien, neuromusculaire.\n\n**Examens de 1re intention** : gazométrie artérielle (gravité, orientation), ECG (embolie pulmonaire, coronaropathie, trouble du rythme), radiographie de thorax, bilan biologique avec NFP, ionogramme, glycémie, BNP/NT-proBNP et D-dimères en cas de suspicion d'embolie pulmonaire.","src":"p. 442-445"},{"id":"203-open-02","type":"OPEN","rank":"A","objective":"203-obj-06","tags":["diagnostic","pièges"],"difficulty":2,"prompt":"Décrivez, sous forme d'arbre décisionnel, la démarche d'orientation étiologique devant une dyspnée aiguë en l'absence de signe de choc, en précisant à chaque étape les pièges à éviter.","rubric":[{"point":"Étape 1 : éliminer un signe de choc (sinon, la prise en charge du choc prime)","weight":1},{"point":"Étape 2 : dyspnée inspiratoire → cause laryngée/trachéale (laisser assis, éviter l'examen de l'oropharynx)","weight":2},{"point":"Étape 3 : dyspnée expiratoire avec ronchi/sibilants → asthme, BPCO ou pseudo-asthme cardiaque","weight":2},{"point":"Étape 4 : crépitants → insuffisance ventriculaire gauche, avec piège du pseudo-asthme cardiaque et de l'œdème lésionnel du SDRA ; penser à la pneumopathie si fièvre/syndrome de condensation","weight":2},{"point":"Étape 5 : syndrome pleural → pneumothorax ou épanchement pleural","weight":1},{"point":"Étape 6 : dyspnée isolée sans orientation → embolie pulmonaire (douleur inconstante), sepsis sévère, anémie, acidose métabolique, puis par élimination syndrome d'hyperventilation/dyspnée psychogène","weight":1},{"point":"Piège transversal : la dyspnée d'origine neuromusculaire est tardive et peut précéder de peu l'arrêt respiratoire","weight":1}],"model":"**1. Signes de choc ?** Oui → la prise en charge hémodynamique du choc prime sur l'analyse de la dyspnée.\n\n**2. Dyspnée inspiratoire ?** Oui → cause laryngée ou trachéale ; laisser le patient assis, éviter l'examen de l'oropharynx (risque de décompensation), penser à une cause néoplasique si l'installation est progressive.\n\n**3. Dyspnée expiratoire avec ronchi/sibilants ?** Oui → asthme, BPCO ou pseudo-asthme cardiaque (piège : sibilants trompeurs pouvant faire méconnaître une origine cardiaque).\n\n**4. Crépitants ?** Oui → oriente vers l'insuffisance ventriculaire gauche, mais attention au pseudo-asthme cardiaque et à l'œdème lésionnel du SDRA qui peuvent aussi donner des crépitants ; en cas de fièvre et de syndrome de condensation, évoquer une pneumopathie.\n\n**5. Syndrome pleural ?** Oui → pneumothorax ou épanchement pleural.\n\n**6. Dyspnée isolée, sans orientation** → évoquer embolie pulmonaire (la douleur thoracique est inconstante), sepsis sévère, anémie ou acidose métabolique ; par élimination, syndrome d'hyperventilation ou dyspnée psychogène.\n\n**Piège transversal** : ne pas sous-estimer une atteinte neuromusculaire, dont la dyspnée est tardive et peut précéder de peu l'arrêt respiratoire.","src":"p. 449-450"},{"id":"203-open-03","type":"OPEN","rank":"B","objective":"203-obj-09","tags":["étiologie","pièges"],"difficulty":3,"prompt":"Comparez, sur le plan clinique, l'œdème aigu du poumon, le pseudo-asthme cardiaque et la tamponnade péricardique comme causes cardiaques de dyspnée aiguë, en insistant sur les éléments permettant de les distinguer.","rubric":[{"point":"OAP : orthopnée, wheezing, crépitants bilatéraux, expectoration rose saumonée, cardiomégalie et œdème alvéolaire radiologiques, FA ou séquelle de nécrose à l'ECG, BNP élevé, amélioration sous diurétique/trinitrine","weight":3},{"point":"Pseudo-asthme cardiaque : équivalent d'OAP à forme bronchospastique, orthopnée avec sibilants ± crépitants — piège avec l'asthme vrai","weight":2},{"point":"Tamponnade : orthopnée, tachycardie, assourdissement des bruits du cœur, auscultation pulmonaire NORMALE, turgescence jugulaire, pouls paradoxal, tableau de collapsus/IVD","weight":3},{"point":"Élément distinctif clé : auscultation pulmonaire pathologique dans l'OAP et le pseudo-asthme cardiaque, strictement normale dans la tamponnade","weight":2}],"model":"**Œdème aigu du poumon** : orthopnée avec wheezing, crépitants bilatéraux à l'auscultation, expectoration rose saumonée ; terrain de cardiopathie connue ou facteur déclenchant (ex. FA) ; radiographie avec cardiomégalie et œdème alvéolaire ; ECG pouvant montrer une séquelle de nécrose ou une FA rapide ; BNP/NT-proBNP augmentés ; amélioration sous diurétique ou trinitrine IV.\n\n**Pseudo-asthme cardiaque** : considéré comme un équivalent d'OAP à forme bronchospastique ; orthopnée avec sibilants ± crépitants — piège classique de confusion avec une authentique crise d'asthme.\n\n**Tamponnade** : complication d'une péricardite avec épanchement ; orthopnée, tachycardie, assourdissement des bruits du cœur, mais surtout une **auscultation pulmonaire normale**, associée à une turgescence jugulaire et un pouls paradoxal (diminution à l'inspiration profonde) ; tableau évocateur d'un collapsus avec signes d'insuffisance ventriculaire droite.\n\n**Distinction clé** : contrairement à l'OAP et au pseudo-asthme cardiaque, l'auscultation pulmonaire de la tamponnade est normale, ce qui doit faire évoquer ce diagnostic devant une dyspnée aiguë sans anomalie auscultatoire pulmonaire.","src":"p. 446-447"},{"id":"203-open-04","type":"OPEN","rank":"A","objective":"203-obj-05","tags":["étiologie","diagnostic","paraclinique"],"difficulty":2,"prompt":"Une femme de 62 ans consulte pour une dyspnée d'aggravation progressive depuis plusieurs mois, stade III de la NYHA. Décrivez la démarche diagnostique devant cette dyspnée chronique, en citant les principaux examens à discuter et les grandes catégories étiologiques à envisager.","rubric":[{"point":"Le bilan peut se faire sans urgence, à la différence de la dyspnée aiguë","weight":1},{"point":"Éliminer en premier lieu une anémie par la NFP","weight":1},{"point":"Examens à discuter : EFR avec gazométrie, ECG, échocardiographie doppler, radiographie de thorax, épreuve d'effort avec mesure des gaz respiratoires, scanner thoracique, cathétérisme cardiaque","weight":3},{"point":"Étiologies cardiaques : toutes les causes d'insuffisance cardiaque, constriction péricardique","weight":2},{"point":"Étiologies pulmonaires : trouble obstructif (BPCO, asthme à dyspnée continue) ou restrictif (PID, pneumoconioses, séquelles pleurales, paralysie phrénique, cyphoscoliose, obésité morbide)","weight":2},{"point":"Penser aussi à l'HTAP et aux causes extracardiopulmonaires (anémie, acidose, neuromusculaire, psychogène)","weight":1}],"model":"**Démarche générale** : contrairement à la dyspnée aiguë, le bilan d'une dyspnée chronique peut se faire sans urgence. La NFP est systématique en premier lieu pour éliminer une anémie avant d'engager des explorations plus poussées.\n\n**Examens à discuter** : EFR avec gazométrie artérielle, ECG, échocardiographie doppler, radiographie de thorax, épreuve d'effort avec mesure des gaz respiratoires et de la consommation d'oxygène (oriente vers une cause cardiaque ou pulmonaire), scanner thoracique pour l'étude du parenchyme, cathétérisme cardiaque notamment si une hypertension pulmonaire est suspectée.\n\n**Étiologies cardiaques** : toutes les causes d'insuffisance cardiaque (valvulaires, ischémiques, cardiomyopathies) et la constriction péricardique.\n\n**Étiologies pulmonaires** : trouble ventilatoire obstructif (BPCO, asthme à dyspnée continue) ou restrictif (pneumopathies infiltrantes diffuses, pneumoconioses, séquelles pleurales post-tuberculeuses, paralysie phrénique, cyphoscoliose, obésité morbide).\n\n**Autres cadres à ne pas oublier** : hypertension artérielle pulmonaire (précapillaire, confirmée par cathétérisme droit) et causes extracardiopulmonaires (anémie, acidose métabolique, atteinte neuromusculaire, syndrome d'hyperventilation).","src":"p. 450-452"}],"edn":[{"id":"203-kfp-01","type":"KFP","rank":"A","objective":"203-obj-03","difficulty":2,"scenario":"M. R., 74 ans, hypertendu et porteur d'une cardiopathie ischémique connue, est amené aux urgences pour une dyspnée brutale survenue au repos il y a une heure, avec impossibilité de rester allongé. Il présente des crépitants bilatéraux et une expectoration mousseuse rosée. Sa fréquence cardiaque est à 118/min, sa SpO2 à 88 % en air ambiant.","questions":[{"stem":"Parmi les signes suivants, lesquels sont en faveur du diagnostic d'œdème aigu du poumon chez ce patient ?","max":3,"options":["Orthopnée","Sibilants isolés sans crépitants","Crépitants bilatéraux à l'auscultation","Expectoration mousseuse rosée","Douleur latérothoracique avec tympanisme","Abolition du murmure vésiculaire d'un côté","Terrain de cardiopathie ischémique connue","Diarrhée fébrile récente","Turgescence jugulaire isolée sans autre signe","Fièvre à 39°C avec frissons"],"correct":[0,2,3],"explanation":"L'OAP associe orthopnée, crépitants bilatéraux et expectoration rose saumonée, volontiers chez un patient à terrain cardiaque connu ; les autres propositions orientent vers d'autres diagnostics (pneumothorax, pneumopathie)."},{"stem":"Quels signes de gravité doivent être recherchés chez ce patient dont la SpO2 est à 88 % ?","max":2,"options":["Cyanose","Notion de voyage en avion récent","Tachycardie > 120/min","Douleur pharyngée","Signes de choc (marbrures)","Antécédent de prothèse de genou","Toux chronique ancienne","Rhinite saisonnière"],"correct":[0,2],"explanation":"Devant une SpO2 < 90 %, il faut rechercher les autres signes de gravité : mise en jeu des muscles accessoires, cyanose, sueurs, tachycardie > 120/min, signes de choc, retentissement neurologique."},{"stem":"Quels éléments paracliniques, s'ils sont retrouvés, renforceraient le diagnostic d'insuffisance cardiaque chez ce patient ?","max":3,"options":["Cardiomégalie avec œdème alvéolaire à la radiographie de thorax","NT-proBNP à 150 pg/mL","Fibrillation atriale rapide à l'ECG","D-dimères négatifs","Épanchement pleural isolé sans opacité","Hyperclarté radiographique avec abolition des vibrations vocales","Amélioration sous trinitrine IV","Syndrome infectieux avec foyer de crépitants systématisé"],"correct":[0,2,6],"explanation":"Cardiomégalie avec œdème alvéolaire, FA rapide à l'ECG et amélioration sous trinitrine IV sont des arguments classiques en faveur de l'OAP ; un NT-proBNP bas (150 pg/mL, < 300) rendrait au contraire l'IC peu probable."}],"src":"p. 444-447"},{"id":"203-kfp-02","type":"KFP","rank":"A","objective":"203-obj-03","difficulty":2,"scenario":"Mme L., 52 ans, opérée d'une prothèse de hanche il y a 10 jours, présente une dyspnée d'apparition brutale sans douleur thoracique associée. L'auscultation cardio-pulmonaire est normale, la fréquence cardiaque est à 105/min.","questions":[{"stem":"Quels éléments de ce tableau sont compatibles avec le diagnostic d'embolie pulmonaire ?","max":3,"options":["Chirurgie récente (contexte postopératoire favorisant)","Installation brutale de la dyspnée","Auscultation cardio-pulmonaire normale","Présence de crépitants bilatéraux","Absence de douleur thoracique éliminant le diagnostic","Fièvre élevée depuis 5 jours","Tachycardie associée","Cyphoscoliose connue","Expectoration purulente abondante"],"correct":[0,1,2],"explanation":"Le contexte postopératoire favorisant, l'installation brutale et l'auscultation normale (sauf tachycardie) sont des éléments compatibles avec une embolie pulmonaire ; l'absence de douleur thoracique n'élimine pas le diagnostic, elle n'est pas constante."},{"stem":"Quel(s) résultat(s) gazométrique(s) serai(en)t typiquement attendu(s) en cas d'embolie pulmonaire ?","max":1,"options":["Hypoxie associée à une hypercapnie","Hypoxie associée à une hypocapnie (effet shunt)","Normoxie avec hypercapnie isolée","Alcalose respiratoire sans hypoxie","Hypercapnie isolée sans anomalie de l'oxygénation","Hypoxie avec normocapnie stricte"],"correct":[1],"explanation":"L'embolie pulmonaire se traduit à la gazométrie par un effet shunt : une hypoxie associée à une hypocapnie, du fait de l'hyperventilation réflexe."},{"stem":"Quel(s) examen(s) de 1re intention doi(ven)t être réalisé(s) chez cette patiente ?","max":3,"options":["Gazométrie artérielle","Électrocardiogramme","Radiographie de thorax","Cathétérisme cardiaque droit d'emblée","Scintigraphie pulmonaire de ventilation/perfusion d'emblée","Épreuve d'effort métabolique d'emblée","Bilan biologique avec D-dimères"],"correct":[0,1,2],"explanation":"Devant toute dyspnée aiguë, les examens de 1re intention sont la gazométrie artérielle, l'ECG et la radiographie de thorax, complétés par un bilan biologique ; les autres examens sont de 2e intention, discutés selon l'orientation."}],"src":"p. 444-447"},{"id":"203-kfp-03","type":"KFP","rank":"A","objective":"203-obj-10","difficulty":3,"scenario":"Mme K., 39 ans, atteinte d'une sclérodermie connue, se plaint depuis plusieurs mois d'une dyspnée d'aggravation progressive à l'effort, sans orthopnée franche. L'examen cardiopulmonaire et la radiographie de thorax sont sensiblement normaux.","questions":[{"stem":"Quels éléments de cette observation orientent vers une hypertension artérielle pulmonaire (HTAP) ?","max":2,"options":["Antécédent de sclérodermie","Examen cardiopulmonaire et radiographie normaux","Orthopnée franche au premier plan","Œdème alvéolaire bilatéral à la radiographie","Cardiomégalie majeure à la radiographie","Fièvre prolongée associée"],"correct":[0,1],"explanation":"La sclérodermie est une des principales causes d'HTAP associée à une connectivité ; un examen et une radiographie normaux sont classiques dans l'HTAP, contrairement aux étiologies cardiaques gauches habituelles."},{"stem":"Quel(s) examen(s) permet(tent) respectivement d'évoquer puis de confirmer le diagnostic d'HTAP ?","max":2,"options":["L'échocardiographie évoque le diagnostic","Le cathétérisme cardiaque droit confirme le diagnostic","La radiographie de thorax confirme seule le diagnostic","L'ECG suffit à confirmer le diagnostic","L'épreuve d'effort seule confirme le diagnostic","La numération formule confirme le diagnostic"],"correct":[0,1],"explanation":"Le diagnostic d'HTAP est évoqué à l'échocardiographie (élévation des pressions pulmonaires) et confirmé par le cathétérisme cardiaque droit, qui mesure la PAPm et la pression capillaire."},{"stem":"Quel(s) critère(s) hémodynamique(s), mesuré(s) au cathétérisme cardiaque droit, définit(ssent) l'HTAP ?","max":2,"options":["PAPm > 25 mmHg au repos","Pression capillaire moyenne < 15 mmHg","PAPm < 15 mmHg au repos","Pression capillaire moyenne > 25 mmHg","Débit cardiaque strictement normal obligatoire","FEVG < 40 %"],"correct":[0,1],"explanation":"L'HTAP est une hypertension pulmonaire précapillaire définie par une PAPm > 25 mmHg au repos (ou > 30 à l'effort) associée à une pression capillaire moyenne < 15 mmHg."}],"src":"p. 451-452"},{"id":"203-tcs-01","type":"TCS","rank":"A","objective":"203-obj-03","difficulty":2,"vignette":"Un homme de 45 ans, sans antécédent notable, consulte pour une dyspnée fébrile évoluant depuis 48 heures, associée à une toux productive.","items":[{"hypothesis":"Si vous pensiez à une pneumopathie infectieuse,","newInfo":"et que vous constatez à l'auscultation un foyer de crépitants localisé avec une opacité systématisée à la radiographie de thorax,","panel":[0,0,1,6,8],"explanation":"Le foyer de crépitants localisé associé à une opacité parenchymateuse systématisée est très en faveur d'une pneumopathie infectieuse, en cohérence avec le contexte fébrile."},{"hypothesis":"Si vous pensiez à une pneumopathie infectieuse,","newInfo":"et que vous constatez une auscultation pulmonaire strictement normale avec une gazométrie montrant une hypoxie-hypocapnie,","panel":[8,5,2,0,0],"explanation":"Une auscultation normale avec effet shunt (hypoxie-hypocapnie) oriente au contraire vers une embolie pulmonaire, et rend la pneumopathie très improbable."},{"hypothesis":"Si vous pensiez à un asthme aigu grave,","newInfo":"et que vous constatez un silence auscultatoire avec disparition du murmure vésiculaire et une élocution impossible,","panel":[0,0,1,5,9],"explanation":"Le silence auscultatoire, la disparition du murmure vésiculaire et l'impossibilité de parler sont les signes classiques et trompeurs de l'asthme aigu grave, urgence vitale."},{"hypothesis":"Si vous pensiez à un asthme aigu grave,","newInfo":"et que vous constatez des sibilants diffus bilatéraux persistants sans autre signe de gravité,","panel":[1,8,4,1,1],"explanation":"La persistance de sibilants diffus, sans silence auscultatoire ni signe de gravité associé, est davantage compatible avec une crise d'asthme simple qu'avec un asthme aigu grave."}],"src":"p. 447-448"},{"id":"203-tcs-02","type":"TCS","rank":"A","objective":"203-obj-03","difficulty":2,"vignette":"Une femme de 68 ans, tabagique, présente une dyspnée aiguë brutale avec douleur thoracique latéralisée à droite.","items":[{"hypothesis":"Si vous pensiez à un pneumothorax,","newInfo":"et que vous constatez une abolition des vibrations vocales et du murmure vésiculaire à droite avec un tympanisme à la percussion,","panel":[0,0,1,6,8],"explanation":"L'abolition des vibrations vocales et du murmure vésiculaire associée à un tympanisme est le tableau clinique classique du pneumothorax."},{"hypothesis":"Si vous pensiez à un pneumothorax,","newInfo":"et que vous constatez une matité franche à la percussion du côté douloureux,","panel":[8,5,2,0,0],"explanation":"Une matité, à l'opposé du tympanisme attendu dans le pneumothorax, oriente plutôt vers un épanchement pleural liquidien et rend le pneumothorax moins probable."},{"hypothesis":"Si vous pensiez à une tamponnade,","newInfo":"et que vous constatez une auscultation pulmonaire normale avec turgescence jugulaire et pouls paradoxal,","panel":[0,0,1,6,8],"explanation":"Auscultation pulmonaire normale, turgescence jugulaire et pouls paradoxal sont les éléments caractéristiques de la tamponnade péricardique."},{"hypothesis":"Si vous pensiez à une tamponnade,","newInfo":"et que vous constatez des crépitants bilatéraux diffus à l'auscultation pulmonaire,","panel":[8,5,2,0,0],"explanation":"Des crépitants bilatéraux ne sont pas attendus dans la tamponnade, dont l'auscultation pulmonaire est classiquement normale ; ce signe oriente plutôt vers un OAP."}],"src":"p. 447-449"},{"id":"203-tcs-03","type":"TCS","rank":"A","objective":"203-obj-10","difficulty":2,"vignette":"Un homme de 66 ans, ancien fumeur, se plaint d'une dyspnée chronique d'aggravation progressive sur plusieurs mois, avec toux productive matinale ancienne.","items":[{"hypothesis":"Si vous pensiez à une BPCO comme cause de la dyspnée chronique,","newInfo":"et que les explorations fonctionnelles respiratoires retrouvent un trouble ventilatoire obstructif,","panel":[0,0,1,6,8],"explanation":"Un trouble ventilatoire obstructif aux EFR, chez un ancien fumeur avec toux chronique, est un argument fort en faveur de la BPCO."},{"hypothesis":"Si vous pensiez à une BPCO comme cause de la dyspnée chronique,","newInfo":"et que l'échocardiographie retrouve une cardiopathie sévère avec élévation des pressions de remplissage,","panel":[8,5,2,0,0],"explanation":"La découverte d'une cardiopathie avec pressions de remplissage élevées oriente vers une cause cardiaque de la dyspnée chronique, rendant la BPCO isolée moins probable comme explication unique."},{"hypothesis":"Si vous pensiez à une numération formule normale éliminant une anémie comme facteur associé,","newInfo":"et que la NFP revient effectivement strictement normale,","panel":[0,0,1,6,8],"explanation":"Une NFP normale permet d'écarter l'anémie comme cause associée de la dyspnée chronique, conformément à la démarche qui recommande de l'éliminer en premier lieu."},{"hypothesis":"Si vous pensiez à une cause obstructive isolée,","newInfo":"et que le patient présente en réalité une orthopnée franche avec crépitants bilatéraux,","panel":[8,5,2,0,0],"explanation":"L'orthopnée franche associée à des crépitants bilatéraux oriente vers une cause cardiaque de la dyspnée chronique plutôt que vers une cause pulmonaire obstructive isolée."}],"src":"p. 450-451"},{"id":"203-tcs-04","type":"TCS","rank":"A","objective":"203-obj-03","difficulty":2,"vignette":"Un enfant de 3 ans, jusque-là bien portant, développe brutalement une dyspnée inspiratoire avec cornage pendant un repas.","items":[{"hypothesis":"Si vous pensiez à une inhalation de corps étranger,","newInfo":"et que le début est brutal, survenu pendant le repas, avec une dyspnée inspiratoire et un cornage,","panel":[0,0,1,6,8],"explanation":"Un début brutal pendant un repas avec dyspnée inspiratoire et cornage est le tableau typique d'une inhalation de corps étranger chez l'enfant."},{"hypothesis":"Si vous pensiez à une inhalation de corps étranger,","newInfo":"et que l'enfant présente en réalité une fièvre élevée évoluant depuis 3 jours avec dysphonie progressive,","panel":[7,5,3,0,0],"explanation":"Une installation progressive sur plusieurs jours avec fièvre oriente davantage vers une cause infectieuse (épiglottite, laryngite) que vers une inhalation de corps étranger, dont le début est brutal."},{"hypothesis":"Si vous pensiez à une épiglottite,","newInfo":"et que l'enfant est fébrile, avec dysphonie et dyspnée inspiratoire d'aggravation progressive,","panel":[0,0,1,6,8],"explanation":"Chez l'enfant, une dyspnée laryngée fébrile d'aggravation progressive avec dysphonie doit faire évoquer une cause infectieuse comme l'épiglottite."},{"hypothesis":"Si vous pensiez à une épiglottite,","newInfo":"et que l'examen de l'oropharynx est réalisé sans précaution particulière,","panel":[2,3,7,2,1],"explanation":"L'examen de l'oropharynx doit être évité en cas de suspicion de corps étranger ou d'épiglottite chez l'enfant, car il expose à un risque de décompensation respiratoire brutale ; cet item ne renforce ni n'infirme directement l'hypothèse mais souligne une conduite à risque."}],"src":"p. 449"}],"trees":[{"id":"203-tree-01","title":"Orientation devant une dyspnée aiguë","rank":"A","objective":"203-obj-14","intro":"L'analyse combinée du terrain, du temps respiratoire concerné et des données de l'auscultation guide le diagnostic étiologique d'une dyspnée aiguë, une fois un éventuel état de choc écarté.","root":"n1","nodes":{"n1":{"type":"question","text":"Existe-t-il des signes de choc (marbrures, angoisse, collapsus) ?","options":[{"label":"Oui","to":"end_choc"},{"label":"Non","to":"n2"}]},"end_choc":{"type":"end","tone":"danger","text":"Traiter le choc en priorité : la dyspnée passe au second plan","note":"La prise en charge hémodynamique prime sur l'enquête étiologique de la dyspnée."},"n2":{"type":"question","text":"La dyspnée est-elle à prédominance inspiratoire (bradypnée, cornage, tirage) ?","options":[{"label":"Oui","to":"end_larynge"},{"label":"Non","to":"n3"}]},"end_larynge":{"type":"end","tone":"warn","text":"Évoquer une cause laryngotrachéale : corps étranger, œdème de Quincke, sténose","note":"Laisser le patient assis, éviter l'examen de l'oropharynx ; une évolution progressive oriente vers une néoplasie."},"n3":{"type":"question","text":"La dyspnée est-elle à prédominance expiratoire avec ronchi ou sibilants ?","options":[{"label":"Oui","to":"end_expi"},{"label":"Non","to":"n4"}]},"end_expi":{"type":"end","tone":"info","text":"Évoquer un asthme, une BPCO ou un pseudo-asthme cardiaque"},"n4":{"type":"question","text":"Des crépitants sont-ils entendus à l'auscultation pulmonaire ?","options":[{"label":"Oui","to":"n4b"},{"label":"Non","to":"n5"}]},"n4b":{"type":"question","text":"Fièvre associée à un syndrome de condensation ou une toux productive ?","options":[{"label":"Oui","to":"end_pneumo"},{"label":"Non","to":"end_oap"}]},"end_pneumo":{"type":"end","tone":"info","text":"Évoquer une pneumopathie infectieuse"},"end_oap":{"type":"end","tone":"warn","text":"Évoquer un œdème aigu du poumon","note":"Ne pas méconnaître un pseudo-asthme cardiaque ou un OAP lésionnel de type SDRA."},"n5":{"type":"question","text":"Existe-t-il un syndrome pleural (abolition du murmure vésiculaire, tympanisme ou matité) ?","options":[{"label":"Oui","to":"end_pleural"},{"label":"Non","to":"n6"}]},"end_pleural":{"type":"end","tone":"info","text":"Évoquer un pneumothorax ou un épanchement pleural"},"n6":{"type":"question","text":"L'examen clinique est-il par ailleurs normal (dyspnée isolée) ?","options":[{"label":"Oui","to":"end_isolee"},{"label":"Non","to":"end_relire"}]},"end_isolee":{"type":"end","tone":"warn","text":"Rechercher embolie pulmonaire, sepsis sévère, anémie ou acidose métabolique ; par élimination, dyspnée psychogène","note":"La douleur thoracique de l'embolie pulmonaire est inconstante."},"end_relire":{"type":"end","tone":"info","text":"Reprendre l'interrogatoire et l'examen à la recherche d'un signe d'orientation manqué"}},"src":"p. 449-450"},{"id":"203-tree-02","title":"Repérer les signes de gravité d'une dyspnée aiguë","rank":"A","objective":"203-obj-15","intro":"Quatre familles de signes cliniques imposent une décision thérapeutique immédiate devant une dyspnée aiguë, avant même la conclusion étiologique.","root":"n1","nodes":{"n1":{"type":"question","text":"Signes de lutte respiratoire (tirage, battement des ailes du nez, balancement thoraco-abdominal) ?","options":[{"label":"Oui","to":"end_lutte"},{"label":"Non","to":"n2"}]},"end_lutte":{"type":"end","tone":"danger","text":"Épuisement ventilatoire : alerter et surveiller de très près"},"n2":{"type":"question","text":"SpO2 < 90 % ?","options":[{"label":"Oui","to":"action_o2"},{"label":"Non","to":"n3"}]},"action_o2":{"type":"action","text":"Débuter l'oxygénothérapie sans attendre","to":"end_hypoxie","note":"Une SpO2 < 90 % témoigne d'une hypoxémie et indique l'oxygène."},"end_hypoxie":{"type":"end","tone":"warn","text":"Compléter par une gazométrie artérielle et surveiller étroitement"},"n3":{"type":"question","text":"Signes de choc (marbrures, tachycardie > 120/min, angoisse) ?","options":[{"label":"Oui","to":"end_choc2"},{"label":"Non","to":"n4"}]},"end_choc2":{"type":"end","tone":"danger","text":"Prise en charge en urgence d'un état de choc"},"n4":{"type":"question","text":"Retentissement neurologique (astérixis, agitation, somnolence, coma) ?","options":[{"label":"Oui","to":"end_neuro"},{"label":"Non","to":"end_norm"}]},"end_neuro":{"type":"end","tone":"danger","text":"Encéphalopathie respiratoire : hypoxémie et/ou hypercapnie sévères à traiter en urgence"},"end_norm":{"type":"end","tone":"ok","text":"Aucun signe de gravité identifié : poursuivre le bilan étiologique standard"}},"src":"p. 444"},{"id":"203-tree-03","title":"Choisir les examens complémentaires devant une dyspnée aiguë","rank":"A","objective":"203-obj-07","intro":"Un socle d'examens de 1re intention est systématique ; les examens de 2e intention sont ensuite dictés par l'orientation clinique et le dosage du peptide natriurétique.","root":"n1","nodes":{"n1":{"type":"action","text":"Prescrire en 1re intention : NFP, gazométrie artérielle, ECG, radiographie de thorax, ionogramme, glycémie","to":"n2"},"n2":{"type":"question","text":"Suspicion clinique d'embolie pulmonaire ?","options":[{"label":"Oui","to":"action_ep"},{"label":"Non","to":"n3"}]},"action_ep":{"type":"action","text":"Demander échodoppler veineux des membres inférieurs et/ou angioscanner pulmonaire et/ou scintigraphie V/Q","to":"end_ep"},"end_ep":{"type":"end","tone":"info","text":"Confirmer ou infirmer l'embolie pulmonaire selon ces résultats"},"n3":{"type":"question","text":"Un dosage du BNP (ou NT-proBNP) a-t-il été demandé ?","options":[{"label":"Oui","to":"n4"},{"label":"Non","to":"end_clin"}]},"end_clin":{"type":"end","tone":"info","text":"Orientation clinique seule ; discuter le dosage si le tableau reste incertain"},"n4":{"type":"question","text":"BNP < 100 pg/mL (ou NT-proBNP < 300 pg/mL) ?","options":[{"label":"Oui","to":"end_bnp_bas"},{"label":"Non","to":"end_bnp_haut"}]},"end_bnp_bas":{"type":"end","tone":"ok","text":"Diagnostic d'insuffisance cardiaque peu probable","note":"Seuils ESC 2021 pour le NT-proBNP, modulés par l'âge : > 450 pg/mL si < 55 ans, > 900 si 55-75 ans, > 1800 si > 75 ans."},"end_bnp_haut":{"type":"end","tone":"warn","text":"Valeurs en faveur d'une insuffisance cardiaque : demander une échocardiographie"}},"src":"p. 444-445"},{"id":"203-tree-04","title":"Orienter une dyspnée chronique","rank":"A","objective":"203-obj-05","intro":"Devant une dyspnée chronique, l'élimination d'une anémie précède tout bilan approfondi ; l'orientation se fait ensuite vers une cause cardiaque, pulmonaire ou vasculaire pulmonaire.","root":"n1","nodes":{"n1":{"type":"question","text":"La numération formule plaquettaire élimine-t-elle une anémie ?","options":[{"label":"Non, anémie présente","to":"end_anemie"},{"label":"Oui, anémie éliminée","to":"n2"}]},"end_anemie":{"type":"end","tone":"warn","text":"Explorer et corriger l'anémie avant d'approfondir le bilan"},"n2":{"type":"question","text":"ECG, radiographie de thorax et échocardiographie en faveur d'une cardiopathie ?","options":[{"label":"Oui","to":"end_cardiaque"},{"label":"Non","to":"n3"}]},"end_cardiaque":{"type":"end","tone":"info","text":"Orientation cardiaque : cardiopathie valvulaire, ischémique, cardiomyopathie ou constriction péricardique"},"n3":{"type":"question","text":"L'EFR met-elle en évidence un trouble ventilatoire obstructif ou restrictif ?","options":[{"label":"Oui","to":"end_pulmonaire"},{"label":"Non","to":"n4"}]},"end_pulmonaire":{"type":"end","tone":"info","text":"Orientation pulmonaire : obstructif (BPCO, asthme) ou restrictif (pneumopathie infiltrante, pneumoconiose, séquelle pleurale, paralysie phrénique, cyphoscoliose, obésité)"},"n4":{"type":"question","text":"L'échocardiographie évoque-t-elle une élévation des pressions pulmonaires ?","options":[{"label":"Oui","to":"n5"},{"label":"Non","to":"end_autre"}]},"n5":{"type":"question","text":"Antécédent d'un ou plusieurs épisodes d'embolie pulmonaire ?","options":[{"label":"Oui","to":"end_htp_embol"},{"label":"Non","to":"end_htap"}]},"end_htp_embol":{"type":"end","tone":"warn","text":"Évoquer une hypertension pulmonaire post-embolique"},"end_htap":{"type":"end","tone":"warn","text":"Évoquer une hypertension artérielle pulmonaire, à confirmer par cathétérisme cardiaque droit","note":"Définie par une PAPm > 25 mmHg au repos (ou > 30 à l'effort) avec pression capillaire < 15 mmHg."},"end_autre":{"type":"end","tone":"info","text":"Rechercher une cause plus rare : acidose métabolique, atteinte neuromusculaire, obstacle des voies aériennes supérieures, syndrome d'hyperventilation"}},"src":"p. 450-452"},{"id":"203-tree-05","title":"Reconnaître un asthme aigu grave","rank":"A","objective":"203-obj-03","intro":"Face à une dyspnée expiratoire fébrile ou non, certains signes doivent immédiatement distinguer la crise d'asthme simple de l'asthme aigu grave, urgence vitale.","root":"n1","nodes":{"n1":{"type":"question","text":"Sibilants entendus à l'auscultation pulmonaire ?","options":[{"label":"Oui","to":"end_simple"},{"label":"Non (silence auscultatoire)","to":"n2"}]},"end_simple":{"type":"end","tone":"ok","text":"Crise d'asthme non grave : traiter et réévaluer"},"n2":{"type":"question","text":"Thorax bloqué en inflation, élocution impossible, murmure vésiculaire aboli ?","options":[{"label":"Oui","to":"end_grave"},{"label":"Non","to":"end_reevaluer"}]},"end_grave":{"type":"end","tone":"danger","text":"Asthme aigu grave : urgence vitale","note":"Un pouls paradoxal est possible."},"end_reevaluer":{"type":"end","tone":"warn","text":"Tableau atypique : réévaluer immédiatement sans méconnaître une forme sévère"}},"src":"p. 447-448"}],"treatments":{"data":[{"id":"203-tx-01","rank":"A","class":"Oxygénothérapie","molecules":[],"context":"Mesure symptomatique immédiate devant une dyspnée aiguë hypoxémiante","indications":["SpO2 < 90 %, témoin d'une hypoxémie"],"contraindications":[],"sideEffects":[],"monitoring":["SpO2","Gazométrie artérielle (hypoxémie, hypercapnie)"],"interactions":[],"pearls":["Une SpO2 < 90 % indique par elle-même l'administration d'oxygène, avant même la conclusion étiologique"],"src":"p. 444"},{"id":"203-tx-02","rank":"A","class":"Diurétique et dérivé nitré intraveineux","molecules":["Trinitrine"],"context":"Traitement d'épreuve devant une suspicion clinique d'œdème aigu du poumon","indications":["Œdème aigu du poumon évoqué cliniquement (orthopnée, crépitants bilatéraux, cardiopathie connue)"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Une réponse favorable au diurétique ou à la trinitrine IV renforce le diagnostic d'OAP"],"src":"p. 446"},{"id":"203-tx-03","rank":"B","class":"Antagoniste des récepteurs de l'endothéline","molecules":["Bosentan (Tracleer®)"],"context":"Thérapeutique spécifique de l'hypertension artérielle pulmonaire","indications":["Hypertension artérielle pulmonaire"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["L'émergence de ces thérapeutiques a nettement amélioré le pronostic, longtemps réservé, de l'HTAP"],"src":"p. 451-452"},{"id":"203-tx-04","rank":"A","class":"Hospitalisation en réanimation","molecules":[],"context":"Prise en charge du syndrome de détresse respiratoire aiguë (SDRA), forme sévère de défaillance pulmonaire aiguë","indications":["SDRA, quelle qu'en soit la cause (infectieuse, inhalation, embolique, traumatique, toxique)"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Le SDRA associe une mortalité élevée et un œdème pulmonaire lésionnel, à distinguer de l'œdème hémodynamique"],"src":"p. 448"},{"id":"203-tx-05","rank":"A","class":"Prise en charge prioritaire d'un état de choc","molecules":[],"context":"Priorité thérapeutique absolue devant une dyspnée aiguë associée à des signes de choc","indications":["Dyspnée aiguë avec marbrures, collapsus ou angoisse évoquant un état de choc"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["La dyspnée s'efface devant la prise en charge du choc, qui doit primer sur l'enquête étiologique"],"src":"p. 449-450"}],"strategies":[{"id":"203-strat-01","rank":"A","title":"Stratégie générale face à une dyspnée aiguë","content":"1. Rechercher en urgence les signes de gravité : mise en jeu des muscles respiratoires accessoires, cyanose, sueurs, tachycardie > 120/min, signes de choc, SpO2 < 90 %, signes neurologiques.\n2. Débuter l'oxygénothérapie sans délai si SpO2 < 90 %.\n3. Réaliser les examens de 1re intention : gazométrie artérielle, ECG, radiographie de thorax, NFP, ionogramme, glycémie, et D-dimères ou BNP/NT-proBNP selon l'orientation.\n4. Orienter le diagnostic selon le temps respiratoire concerné (inspiratoire, expiratoire), l'auscultation (crépitants, sibilants) et la présence d'un syndrome pleural.\n5. Compléter, selon l'étiologie suspectée, par des examens de 2e intention : échodoppler veineux, angioscanner ou scintigraphie pulmonaire, échocardiographie, épreuves fonctionnelles respiratoires.","src":"p. 444-450"},{"id":"203-strat-02","rank":"A","title":"Conduite devant une suspicion d'œdème aigu du poumon","content":"1. Rechercher les arguments cliniques évocateurs : orthopnée, wheezing, crépitants bilatéraux, expectoration rose saumonée, terrain de cardiopathie connue ou facteur déclenchant tel qu'une fibrillation atriale.\n2. Rechercher les arguments paracliniques : radiographie de thorax (œdème alvéolaire, cardiomégalie), ECG (onde Q de nécrose, fibrillation atriale rapide), BNP ou NT-proBNP augmenté.\n3. Débuter un traitement d'épreuve par diurétique ou trinitrine intraveineuse ; une réponse favorable constitue un argument supplémentaire en faveur du diagnostic.","src":"p. 446"}]},"cases":[{"id":"203-case-01","title":"M. Vasseur, 71 ans, dyspnée brutale au décours d'une chirurgie orthopédique","rank":"A","summary":"Dyspnée aiguë isolée chez un patient récemment opéré d'une prothèse de hanche, menant au diagnostic d'embolie pulmonaire puis à une complication chronique à distance.","difficulty":2,"timeline":["Consultation initiale","Examen clinique et gravité","Bilan de 1re intention","Confirmation diagnostique","Prise en charge initiale","Suivi à 3 mois"],"steps":[{"id":"203-case-01-s01","phase":0,"narrative":"M. Vasseur, 71 ans, opéré d'une prothèse totale de hanche trois semaines plus tôt, consulte pour un essoufflement d'apparition brutale depuis la veille, sans douleur thoracique franche.","question":{"type":"QRM","stem":"Parmi les éléments suivants, lesquels orientent vers une embolie pulmonaire chez ce patient ?","options":[{"t":"Le contexte postopératoire récent","ok":true,"why":"L'immobilisation et la chirurgie récente sont des facteurs favorisants classiques."},{"t":"Une auscultation cardiopulmonaire habituellement normale","ok":true,"why":"L'auscultation de l'embolie pulmonaire est souvent normale, en dehors d'une tachycardie."},{"t":"Une douleur thoracique inconstante","ok":true,"why":"La dyspnée est en règle associée à une douleur thoracique, mais celle-ci peut manquer."},{"t":"Une fièvre élevée d'emblée","ok":false,"why":"La fièvre oriente davantage vers une pneumopathie infectieuse."},{"t":"Des crépitants bilatéraux diffus","ok":false,"why":"Ce signe oriente plutôt vers un œdème aigu du poumon ou une pneumopathie."}],"explanation":"Le terrain postopératoire, l'installation brutale et une auscultation pauvre sont évocateurs d'embolie pulmonaire."},"reveal":"L'examen retrouve une fréquence cardiaque à 110/min, une SpO2 à 88 % en air ambiant, une auscultation cardiopulmonaire normale et l'absence de fièvre.","src":"p. 447"},{"id":"203-case-01-s02","phase":1,"narrative":"Devant cette SpO2 basse, l'équipe s'interroge sur la conduite immédiate à tenir avant même de poursuivre le bilan.","question":{"type":"QRM","stem":"Concernant la SpO2 mesurée à 88 %, quelles affirmations sont exactes ?","options":[{"t":"Une SpO2 < 90 % témoigne d'une hypoxémie","ok":true,"why":"C'est la définition retenue dans le chapitre."},{"t":"Elle indique l'administration immédiate d'oxygène","ok":true,"why":"Une SpO2 < 90 % indique l'oxygénothérapie."},{"t":"Elle doit faire différer la gazométrie artérielle","ok":false,"why":"La gazométrie artérielle reste un examen de 1re intention à réaliser sans délai."},{"t":"Elle élimine à elle seule une embolie pulmonaire","ok":false,"why":"Une SpO2 basse n'élimine rien ; elle traduit la gravité, pas l'étiologie."},{"t":"Elle est un signe de gravité devant une dyspnée aiguë","ok":true,"why":"La SpO2 < 90 % fait partie des signes de gravité à rechercher."}],"explanation":"Une SpO2 < 90 % impose l'oxygénothérapie et signe une hypoxémie à documenter par la gazométrie."},"reveal":"Une oxygénothérapie est débutée sans délai ; la SpO2 remonte à 94 % sous 3 L/min.","src":"p. 444"},{"id":"203-case-01-s03","phase":1,"narrative":"L'examen ne retrouve ni marbrures, ni confusion, ni tirage ; la pression artérielle est à 128/78 mmHg.","question":{"type":"QRM","stem":"Quels signes, s'ils avaient été présents, auraient traduit une gravité immédiate imposant une décision thérapeutique urgente ?","options":[{"t":"Un tirage sus-sternal ou un battement des ailes du nez","ok":true,"why":"Ce sont des signes de mise en jeu des muscles respiratoires accessoires."},{"t":"Des marbrures","ok":true,"why":"Elles traduisent un état de choc."},{"t":"Une SpO2 < 90 %","ok":true,"why":"C'est un signe de gravité reconnu."},{"t":"Une toux sèche isolée","ok":false,"why":"Ce n'est pas un signe de gravité en tant que tel."},{"t":"Une matité localisée à une base","ok":false,"why":"C'est un signe d'orientation étiologique (syndrome pleural), pas un signe de gravité."}],"explanation":"Les signes de gravité combinent mise en jeu des muscles accessoires, cyanose, signes de choc, hypoxémie et retentissement neurologique."},"reveal":"Aucun signe de gravité supplémentaire n'est retrouvé ; le bilan de 1re intention est complété.","src":"p. 444"},{"id":"203-case-01-s04","phase":2,"narrative":"La gazométrie artérielle sous air, réalisée avant l'oxygénothérapie, est rapportée.","question":{"type":"QROC","question":"Quel profil gazométrique est classiquement retrouvé dans l'embolie pulmonaire ?","answer":"Un effet shunt avec hypoxémie et hypocapnie","accept":["hypoxie-hypocapnie","hypoxémie avec hypocapnie"],"keywords":["hypoxémie","hypocapnie","effet shunt"],"explanation":"La gazométrie artérielle de l'embolie pulmonaire retrouve typiquement un effet shunt : hypoxémie associée à une hypocapnie."},"reveal":"La gazométrie confirme une hypoxémie avec hypocapnie, compatible avec un effet shunt.","src":"p. 447"},{"id":"203-case-01-s05","phase":2,"narrative":"L'ECG montre une tachycardie sinusale isolée ; la radiographie de thorax est sans anomalie parenchymateuse, pleurale ni médiastinale.","question":{"type":"QRM","stem":"Devant cette dyspnée isolée, sans crépitant ni syndrome pleural, quels diagnostics doivent être évoqués ?","options":[{"t":"Embolie pulmonaire","ok":true,"why":"C'est la cause classique de dyspnée isolée à rechercher en priorité."},{"t":"Sepsis sévère","ok":true,"why":"Un sepsis sévère peut se traduire par une dyspnée isolée."},{"t":"Anémie","ok":true,"why":"L'anémie aiguë peut entraîner une dyspnée sans anomalie auscultatoire."},{"t":"Acidose métabolique","ok":true,"why":"Une acidose métabolique peut donner une polypnée sans signe auscultatoire spécifique."},{"t":"Pneumothorax","ok":false,"why":"Le pneumothorax s'accompagne d'un syndrome pleural, absent ici."}],"explanation":"Devant une dyspnée isolée, il faut penser à l'embolie pulmonaire, au sepsis sévère, à l'anémie et à l'acidose métabolique ; par élimination, à un syndrome d'hyperventilation."},"reveal":"La numération formule plaquettaire est normale, écartant une anémie ; un dosage de D-dimères et de BNP est demandé.","src":"p. 449"},{"id":"203-case-01-s06","phase":2,"narrative":"Les D-dimères reviennent élevés ; le BNP est normal.","question":{"type":"QRM","stem":"Quels éléments biologiques rendent le diagnostic d'insuffisance cardiaque peu probable ici ?","options":[{"t":"Un BNP strictement normal","ok":true,"why":"Un BNP < 100 pg/mL rend le diagnostic d'IC peu probable devant une dyspnée aiguë."},{"t":"Un NT-proBNP < 300 pg/mL","ok":true,"why":"C'est le seuil retenu pour écarter une IC devant une dyspnée aiguë."},{"t":"Des D-dimères élevés","ok":false,"why":"Les D-dimères orientent vers l'embolie pulmonaire, pas vers l'IC."},{"t":"Une cardiomégalie à la radiographie","ok":false,"why":"Elle est absente ici et n'a pas été observée."},{"t":"Un BNP > 500 pg/mL","ok":false,"why":"Une valeur élevée serait au contraire en faveur d'une IC, non le cas ici."}],"explanation":"Un BNP bas rend l'insuffisance cardiaque peu probable et renforce la suspicion d'une autre cause, ici l'embolie pulmonaire."},"reveal":"Le BNP normal écarte une insuffisance cardiaque ; les D-dimères élevés confortent la suspicion d'embolie pulmonaire.","src":"p. 445"},{"id":"203-case-01-s07","phase":3,"narrative":"Face à cette suspicion clinique et biologique d'embolie pulmonaire, un examen de confirmation est demandé.","question":{"type":"QROC","question":"Quel examen de 2e intention permet de confirmer une embolie pulmonaire évoquée sur ce tableau ?","answer":"L'angioscanner pulmonaire (ou la scintigraphie pulmonaire de ventilation/perfusion)","accept":["angioscanner thoracique","scintigraphie V/Q"],"keywords":["angioscanner","pulmonaire","scintigraphie"],"explanation":"En cas de suspicion d'embolie pulmonaire, l'échodoppler veineux des membres inférieurs, l'angioscanner pulmonaire et la scintigraphie de ventilation/perfusion sont discutés."},"reveal":"L'angioscanner pulmonaire confirme des emboles lobaires bilatéraux.","src":"p. 445"},{"id":"203-case-01-s08","phase":3,"narrative":"Le diagnostic est confirmé. L'équipe évalue la tolérance hémodynamique pour décider de la prise en charge.","question":{"type":"QRM","stem":"Quels éléments traduiraient une mauvaise tolérance hémodynamique imposant une prise en charge en urgence absolue ?","options":[{"t":"Des signes de choc","ok":true,"why":"Les signes de choc traduisent une mauvaise tolérance et priment sur tout le reste."},{"t":"Des marbrures","ok":true,"why":"C'est un signe d'état de choc."},{"t":"Un collapsus tensionnel","ok":true,"why":"Le collapsus signe une mauvaise tolérance hémodynamique."},{"t":"Une SpO2 à 95 % sous oxygène","ok":false,"why":"Cette valeur traduit au contraire une bonne réponse à l'oxygénothérapie."},{"t":"Une auscultation cardiopulmonaire normale","ok":false,"why":"C'est la présentation habituelle de l'embolie pulmonaire, pas un signe de gravité en soi."}],"explanation":"Les signes de choc, les marbrures et le collapsus définissent une embolie pulmonaire mal tolérée, imposant la prise en charge du choc en priorité."},"reveal":"M. Vasseur ne présente aucun signe de choc ; son état reste stable sous oxygène.","src":"p. 444"},{"id":"203-case-01-s09","phase":4,"narrative":"L'interne demande ce qu'il aurait fallu faire si des signes de choc avaient accompagné cette dyspnée.","question":{"type":"QROC","question":"Si ce patient avait présenté des signes de choc associés, quelle aurait été la priorité de prise en charge ?","answer":"La prise en charge du choc, qui prime et relègue la dyspnée au second plan","accept":["traiter le choc en premier"],"keywords":["choc","priorité"],"explanation":"Dans une dyspnée avec état de choc, la dyspnée s'efface devant la prise en charge du choc."},"reveal":"M. Vasseur est hospitalisé pour surveillance et poursuite de la prise en charge de son embolie pulmonaire.","src":"p. 449"},{"id":"203-case-01-s10","phase":5,"narrative":"Trois mois plus tard, M. Vasseur revient consulter car il reste dyspnéique à la montée de deux étages, alors qu'il ne l'était pas auparavant.","question":{"type":"QRM","stem":"Quelle complication chronique doit être évoquée après un ou plusieurs épisodes d'embolie pulmonaire ?","options":[{"t":"Une hypertension pulmonaire post-embolique","ok":true,"why":"C'est une complication grave de la maladie thromboembolique avec persistance d'une hypertension pulmonaire précapillaire."},{"t":"Un œdème aigu du poumon","ok":false,"why":"Rien dans ce tableau n'oriente vers une cause cardiogénique aiguë."},{"t":"Un pneumothorax","ok":false,"why":"Aucun syndrome pleural n'est décrit."},{"t":"Une crise d'asthme","ok":false,"why":"Aucun antécédent ni sibilant ne l'évoque."},{"t":"Une tamponnade","ok":false,"why":"Aucun signe évocateur de péricardite ou de tamponnade n'est rapporté."}],"explanation":"La persistance d'une hypertension pulmonaire précapillaire après un ou plusieurs épisodes emboliques définit l'hypertension pulmonaire post-embolique."},"reveal":"Une échocardiographie est demandée pour rechercher une élévation des pressions pulmonaires.","src":"p. 452"},{"id":"203-case-01-s11","phase":5,"narrative":"L'échocardiographie retrouve des signes évocateurs d'une élévation des pressions pulmonaires.","question":{"type":"QROC","question":"Quel examen invasif confirme le diagnostic d'hypertension pulmonaire précapillaire ?","answer":"Le cathétérisme cardiaque droit","accept":["cathétérisme droit"],"keywords":["cathétérisme","cardiaque","droit"],"explanation":"Le diagnostic d'hypertension pulmonaire précapillaire est confirmé par le cathétérisme cardiaque droit, qui mesure la PAPm et la pression capillaire."},"reveal":"Le cathétérisme cardiaque droit confirme une hypertension pulmonaire post-embolique ; un suivi spécialisé est organisé.","src":"p. 451-452"},{"id":"203-case-01-s12","phase":5,"narrative":"Le dossier de M. Vasseur est repris en synthèse avec l'externe pour resituer l'ensemble de la démarche.","question":{"type":"OPEN","prompt":"Résumez, dans l'ordre, la démarche diagnostique suivie chez ce patient, depuis la dyspnée aiguë jusqu'à la complication à 3 mois.","rubric":[{"point":"Élimination d'un état de choc puis recherche des signes de gravité","weight":1},{"point":"Bilan de 1re intention (gazométrie, ECG, radiographie, NFP, D-dimères, BNP)","weight":1},{"point":"Orientation vers l'embolie pulmonaire devant une dyspnée isolée avec BNP normal","weight":1},{"point":"Confirmation par angioscanner pulmonaire","weight":1},{"point":"Surveillance à distance et dépistage d'une hypertension pulmonaire post-embolique","weight":1}],"model":"Après avoir écarté un état de choc et des signes de gravité, le bilan de 1re intention (gazométrie montrant un effet shunt, ECG, radiographie normale, NFP normale, D-dimères élevés, BNP normal) oriente vers une dyspnée isolée évocatrice d'embolie pulmonaire, confirmée par angioscanner pulmonaire. La tolérance hémodynamique étant bonne, une simple hospitalisation est décidée. À 3 mois, la persistance d'une dyspnée d'effort fait rechercher une hypertension pulmonaire post-embolique, confirmée par cathétérisme cardiaque droit après une échocardiographie évocatrice."},"reveal":"La synthèse est validée ; un suivi cardiologique régulier est programmé.","src":"p. 444-452"}]},{"id":"203-case-02","title":"M. Perrin, 74 ans, essoufflement d'aggravation progressive","rank":"A","summary":"Dyspnée chronique progressive chez un ancien fumeur avec antécédent de BPCO, aboutissant au diagnostic d'insuffisance cardiaque à fraction d'éjection préservée après élimination des pièges classiques.","difficulty":2,"timeline":["Consultation","NYHA et interrogatoire","Examen clinique","Bilan de 1re intention","Bilan de 2e intention","Diagnostic et surveillance"],"steps":[{"id":"203-case-02-s01","phase":0,"narrative":"M. Perrin, 74 ans, ancien fumeur avec un antécédent de BPCO modérée, consulte pour un essoufflement qui s'aggrave progressivement depuis six mois.","question":{"type":"QRM","stem":"Quels éléments de l'interrogatoire faut-il préciser en priorité devant cette dyspnée chronique ?","options":[{"t":"La rapidité d'installation exacte","ok":true,"why":"Il faut distinguer une évolution chronique d'une aggravation plus récente."},{"t":"Le stade fonctionnel selon la classification NYHA","ok":true,"why":"L'intensité de la dyspnée est évaluée par la NYHA."},{"t":"Les circonstances déclenchantes et la position (orthopnée)","ok":true,"why":"Ces éléments orientent vers une origine cardiaque ou pulmonaire."},{"t":"Le groupe sanguin","ok":false,"why":"Cette donnée n'a pas d'intérêt dans l'orientation d'une dyspnée."},{"t":"La couleur des urines","ok":false,"why":"Cet élément n'est pas mentionné comme pertinent pour la dyspnée."}],"explanation":"L'interrogatoire précise le caractère aigu ou chronique, le stade NYHA et les circonstances de survenue de la dyspnée."},"reveal":"M. Perrin rapporte un essoufflement à la marche en terrain plat, l'obligeant parfois à s'arrêter.","src":"p. 443"},{"id":"203-case-02-s02","phase":1,"narrative":"Le stade fonctionnel doit être précisé selon la classification NYHA.","question":{"type":"QRM","stem":"Concernant la classification NYHA, quelles affirmations sont exactes ?","options":[{"t":"Stade I : absence de dyspnée pour les efforts habituels de la vie courante","ok":true,"why":"C'est la définition du stade I."},{"t":"Stade II : dyspnée pour des efforts importants (marche rapide, côte, > 2 étages)","ok":true,"why":"C'est la définition du stade II."},{"t":"Stade III : dyspnée pour des efforts peu intenses (terrain plat, < 2 étages)","ok":true,"why":"C'est la définition du stade III, correspondant à ce patient."},{"t":"Stade IV : dyspnée uniquement pour les efforts intenses","ok":false,"why":"Le stade IV correspond à une dyspnée permanente de repos ou pour des efforts minimes."},{"t":"L'échelle NYHA est réservée à la pneumologie","ok":false,"why":"C'est l'échelle MRC qui est utilisée en pneumologie, la NYHA étant la plus utilisée en général."}],"explanation":"Le patient se situe au stade III : dyspnée pour des efforts peu intenses de la vie courante."},"reveal":"M. Perrin est classé stade III de la NYHA.","src":"p. 443"},{"id":"203-case-02-s03","phase":2,"narrative":"L'examen retrouve des crépitants fins aux deux bases pulmonaires, sans sibilant ni ronchi, sans anomalie de percussion.","question":{"type":"QRM","stem":"Quels signes auscultatoires orientent vers une origine cardiaque de la dyspnée plutôt qu'une origine pulmonaire obstructive ?","options":[{"t":"Des crépitants bilatéraux","ok":true,"why":"La présence de crépitants oriente vers l'insuffisance ventriculaire gauche."},{"t":"Des sibilants ou ronchi","ok":false,"why":"Ils orientent au contraire vers l'asthme ou la BPCO."},{"t":"Un tympanisme à la percussion","ok":false,"why":"C'est un signe évocateur de pneumothorax."},{"t":"Une abolition du murmure vésiculaire localisée","ok":false,"why":"Elle oriente vers un épanchement pleural."},{"t":"Une auscultation strictement normale","ok":false,"why":"Ce n'est pas le cas ici et n'oriente pas spécifiquement vers une cause cardiaque."}],"explanation":"La présence de crépitants bilatéraux oriente vers l'insuffisance ventriculaire gauche, en gardant à l'esprit le piège du pseudo-asthme cardiaque."},"reveal":"Aucun œdème des membres inférieurs n'est retrouvé ; la pression artérielle est à 142/86 mmHg.","src":"p. 444"},{"id":"203-case-02-s04","phase":3,"narrative":"Avant tout bilan approfondi, un examen biologique simple est systématiquement demandé.","question":{"type":"QROC","question":"Quel examen biologique de 1re intention doit systématiquement être vérifié pour éliminer une cause fréquente et simple de dyspnée chronique ?","answer":"La numération formule plaquettaire, pour éliminer une anémie","accept":["NFP","numération formule sanguine"],"keywords":["numération","anémie"],"explanation":"Il faut toujours éliminer une anémie avant de se lancer dans des bilans plus poussés devant une dyspnée chronique."},"reveal":"La numération formule plaquettaire est normale ; l'ECG montre des signes de surcharge auriculaire gauche et la radiographie une silhouette cardiaque à la limite supérieure de la normale.","src":"p. 450"},{"id":"203-case-02-s05","phase":3,"narrative":"L'antécédent de BPCO chez ce patient encombré au réveil incite l'interne à évoquer d'emblée un œdème aigu du poumon.","question":{"type":"QRM","stem":"Quels pièges diagnostiques classiques faut-il garder à l'esprit chez ce patient BPCO dyspnéique ?","options":[{"t":"Porter par excès le diagnostic d'OAP chez un patient BPCO encombré","ok":true,"why":"C'est un piège classique rappelé dans le chapitre."},{"t":"Méconnaître une anémie associée","ok":true,"why":"Il faut toujours y penser devant une dyspnée, quel que soit le terrain."},{"t":"Négliger un tableau trompeur de pseudo-asthme cardiaque","ok":true,"why":"Le pseudo-asthme cardiaque est un tableau trompeur classiquement cité."},{"t":"Réaliser systématiquement un angioscanner pulmonaire en 1re intention","ok":false,"why":"L'angioscanner n'est indiqué qu'en cas de suspicion d'embolie pulmonaire."},{"t":"Hospitaliser systématiquement en réanimation","ok":false,"why":"Ce n'est pas la règle générale devant une dyspnée chronique sans signe de gravité."}],"explanation":"Le diagnostic d'OAP est souvent porté par excès chez le BPCO encombré ; il faut aussi penser à l'anémie et se méfier des tableaux trompeurs."},"reveal":"Le bilan est poursuivi sans conclusion hâtive à un OAP isolé.","src":"p. 453"},{"id":"203-case-02-s06","phase":4,"narrative":"Le diagnostic restant incertain entre origine cardiaque et pulmonaire, un examen fonctionnel est proposé.","question":{"type":"QROC","question":"Quel examen objective la gêne respiratoire à l'effort et permet une orientation plus objective vers une cause cardiaque ou pulmonaire ?","answer":"L'épreuve d'effort avec mesure des gaz respiratoires et de la consommation d'oxygène","accept":["épreuve d'effort métabolique","VO2"],"keywords":["épreuve","effort","gaz","oxygène"],"explanation":"Cet examen permet une évaluation objective de la gêne respiratoire et oriente vers une cause plutôt cardiaque ou pulmonaire."},"reveal":"Une échocardiographie doppler est également programmée.","src":"p. 450"},{"id":"203-case-02-s07","phase":4,"narrative":"L'échocardiographie retrouve une fraction d'éjection ventriculaire gauche préservée à 60 %, avec des signes en faveur d'une élévation des pressions de remplissage.","question":{"type":"QRM","stem":"Parmi les étiologies cardiaques de dyspnée chronique citées, lesquelles sont à connaître ?","options":[{"t":"Les cardiopathies valvulaires","ok":true,"why":"Elles font partie des causes d'insuffisance cardiaque citées."},{"t":"Les cardiopathies ischémiques","ok":true,"why":"Elles font partie des causes d'insuffisance cardiaque citées."},{"t":"La constriction péricardique","ok":true,"why":"Elle est citée comme cause cardiaque de dyspnée chronique."},{"t":"La pneumoconiose","ok":false,"why":"C'est une cause pulmonaire restrictive, non cardiaque."},{"t":"La BPCO","ok":false,"why":"C'est une cause pulmonaire obstructive, non cardiaque."}],"explanation":"Les étiologies cardiaques de dyspnée chronique regroupent toutes les causes d'insuffisance cardiaque (valvulaire, ischémique, cardiomyopathie, IC à fonction préservée) et la constriction péricardique."},"reveal":"Le tableau échocardiographique est compatible avec une insuffisance cardiaque à fraction d'éjection préservée.","src":"p. 451"},{"id":"203-case-02-s08","phase":5,"narrative":"L'ensemble du bilan (crépitants bilatéraux, anémie éliminée, échocardiographie évocatrice) est réuni pour conclure.","question":{"type":"QRU","stem":"Quel diagnostic retenez-vous en synthèse chez ce patient ?","options":[{"t":"Insuffisance cardiaque à fraction d'éjection préservée","ok":true,"why":"C'est le diagnostic cohérent avec l'ensemble du tableau clinique et échocardiographique."},{"t":"Exacerbation isolée de BPCO","ok":false,"why":"L'auscultation ne retrouve pas de sibilant ni de ronchi évocateurs."},{"t":"Anémie chronique","ok":false,"why":"La numération formule plaquettaire est normale."},{"t":"Hypertension artérielle pulmonaire idiopathique","ok":false,"why":"Le tableau échocardiographique oriente ici vers une cardiopathie gauche, non vers une HTAP isolée."},{"t":"Hypertension pulmonaire post-embolique","ok":false,"why":"Aucun antécédent d'embolie pulmonaire n'est rapporté."}],"explanation":"Le tableau clinique et échocardiographique est en faveur d'une insuffisance cardiaque à fraction d'éjection préservée."},"reveal":"Un traitement et un suivi spécialisés sont organisés pour cette insuffisance cardiaque à fraction d'éjection préservée.","src":"p. 451"},{"id":"203-case-02-s09","phase":5,"narrative":"L'externe doit synthétiser la stratégie de bilan suivie pour ce patient dyspnéique chronique.","question":{"type":"OPEN","prompt":"Décrivez et justifiez la stratégie de bilan complémentaire proposée chez ce patient dyspnéique chronique.","rubric":[{"point":"NFP en premier lieu pour éliminer une anémie","weight":1},{"point":"ECG et radiographie de thorax pour une première orientation","weight":1},{"point":"Échocardiographie doppler devant l'orientation clinique cardiaque","weight":1},{"point":"Épreuve d'effort métabolique en cas de doute persistant entre origine cardiaque et pulmonaire","weight":1}],"model":"Devant une dyspnée chronique, la numération formule plaquettaire élimine en premier lieu une anémie. L'ECG et la radiographie de thorax orientent ensuite vers une cause cardiaque ou pulmonaire. L'échocardiographie doppler, ici en faveur d'une insuffisance cardiaque à fraction préservée, confirme l'orientation clinique ; une épreuve d'effort métabolique aurait pu être discutée en cas de doute persistant."},"reveal":"La stratégie est validée par le senior.","src":"p. 450-451"},{"id":"203-case-02-s10","phase":5,"narrative":"Le senior demande de justifier la conduite à tenir si une hypertension pulmonaire avait été suspectée à l'échocardiographie.","question":{"type":"QRM","stem":"Si l'échocardiographie avait évoqué une hypertension pulmonaire, quels examens permettraient de l'explorer ?","options":[{"t":"Le cathétérisme cardiaque droit","ok":true,"why":"Il confirme le diagnostic d'hypertension pulmonaire précapillaire."},{"t":"L'échocardiographie elle-même","ok":true,"why":"Elle permet d'évoquer une élévation des pressions pulmonaires en première intention."},{"t":"La radiographie de thorax seule","ok":false,"why":"Elle peut rester normale et n'est pas un examen de confirmation."},{"t":"Les EFR seules","ok":false,"why":"Elles ne confirment pas une hypertension pulmonaire d'origine cardiaque."},{"t":"L'angioscanner pulmonaire systématique","ok":false,"why":"Il n'est pas systématique en l'absence de suspicion embolique."}],"explanation":"Le diagnostic d'hypertension pulmonaire est évoqué à l'échocardiographie et confirmé par le cathétérisme cardiaque droit."},"reveal":"Chez M. Perrin, l'orientation reste celle d'une insuffisance cardiaque à fraction préservée, sans nécessité de cathétérisme dans l'immédiat.","src":"p. 451-452"}]}],"ecg":{"data":[],"method":""},"echo":{"data":[]}});
